INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_title','هزینه کاشت ریحان با نوار تیپ در هکتار: راهنمای کامل' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_title');
INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','راهنمای جامع و کاربردی محاسبه هزینه کشت ریحان با استفاده از روش نوار تیپ (Tip Tape) در هر هکتار برای کشاورزان عراقي. تحلیل کامل هزینه‌ها و مزایای این روش.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'rank_math_focus_keyword','تفاوت هزینه کاشت ریحان با روش نوار تیپ در هر هکتار: راهنمای جامع و کاربردی' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='rank_math_focus_keyword');
