INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддима дар бораи иқтисоди кадакунии риҳан бо обёривии муосир</h2><p>Ҷуи риҳан (Basil) бо сабаби истифодаи васеъ дар саноати озувориш, тиббӣ ва офтобӣ яке аз маҳсулоти кӯлӣ дорад. Кадакунии анъанавии ин ҷу на танҳо истеъмоли оби баланд дорад, балки хароҷоти кору идораро низ афзун мекунад. Дар муқобил, истифода аз <strong>навари дрип</strong> ё обёривии қатрагӣ муосир имкони назорати дақиқро бар об ва моддаҳои ғизоӣ фароҳам меорад. Мақсади асосии ин мақола <strong>хараҷоти кадакунии риҳан бо навари дрип дар як гектар</strong> аст, то ки деҳқонон ташхиси дақиқтар аз муваффақияти сармояи худ дошта бошанд.</p><p>Риҳан ҷуе аст, ки ба рӯшноии офтоб, ҳарорати муносиб ва намудории мувофиқ ниёз дорад. Бо истифода аз навари дрип, шумо метавонед намудории решаҳоро тоқу ташаккулӣ таъмин кунед, ки бевосита ба сифат ва вазни маҳсулоти ниҳоӣ таъсир мерасонад. Биёед ҳамгӣ муҳимтарин омили таъсиркунанда ба хараҷоти ниҳоиро баррасӣ кунем.</p><h2>Таҳлили қисматҳои хараҷоти кадакунии риҳан бо навари дрип дар як гектар</h2><p>Барои ҳисоб кардани дақиқи арзиши парвариши риҳон бо навар чип дар як гектар, бояд сарфаҳаро ба ду гурӯҳи доимӣ (сармоявӣ) ва тағйирёбанда (фоидаандоз) ҷудо кунем. Дар идома мо муносибатҳои ҳар қисматро баррасӣ менамоем.</p><h3>Арзиши замин ва омода кардани он</h3><ul><li><strong>Ижора ё моликияти замин:</strong> Вобаста ба мақоми ҷуғрофӣ, ин қисмат метавонад тағйирёбии назаррас дошта бошад.</li><li><strong>Дастӣ ва тоза кардани замин:</strong> Дарбаргиранди ҳавокуниш, хароб кардани пухтаҳои чархуғонҳо ва омода кардани замина барои кӯркарди риҳон.</li><li><strong>Харидани қамчаҳо ё пухтаҳои риҳон:</strong> Сифати пухтаҳо ё қамчаҳои риҳон ба ҳосилнокии ибтидоӣ таъсири ҷонӣ мекунад. Тавсия мешавад, ки қамчаҳои солим ва бе беморӣ истифода шавад.</li></ul><p>Агар шумо ба таҳлил муқоисавӣ барои мавсимиҳои дигари монанд ниёз доред, метавонед ба роҳнамои <a href="https://navar-abyari.ir/miqdori-tukhmi-shambalila-baroyi-yak-hektar/">Миқдори тоҳи чинҷифил барои як гектар</a> нигаред, то истиноф бо маърифат беҳтар дошта бошед, гарчанде ки чинҷифил одатан бо нӯр (қалъа) парҳез мешавад.</p><h3>Арзиши системаи навори дӯппа ва лӯлакашӣ</h3><p>Қисми зиёди хашми парҳези чинҷифил бо навори дӯппа дар як гектар ба системаи обёрӣ махсус карда мешавад. Шумо ба навори дӯппаи сифатнок ниёз доред, ки устувории баланд дорад ба қаблӣ ва фишори об. Интихоби навори дӯппа бо қалқории муносиб диوار муҳим аст. Барои шиносоӣ бо он, ки қалқори дивор чӣ гуна ба умри навор таъсир мерасонад, метавонед мақолаи <a href="https://navar-abyari.ir/ideal-wall-thickness-drip-tape-irrigation/">Қалқори иделали дивари навори дӯппа дар обёрӣ</a> ро хонед. Наворҳои бо қалқори баландтар метавонанд каме гаронтар бошанд, вале хатарро буриданро кам мекунанд.</p><p>Илова бар навор, шумо ба лӯлаи асосӣ, тӯп, филтр ва помпаи обёрӣ ниёз доред. Ин авъор як бор харидорӣ мешаванд ва метавонанд дар солҳои оянда низ истифода шаванд, бинобар ин хашми онҳо дар ҳисобҳои соли аввал баландтар ба назар мерасад, аммо дар солҳои оянда ҳамчун истреоҳисобӣ мешавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/هزینه-کشت-ریحان-با-نوار-تیپ-در-هکتار-تصویر-شاخص.webp" alt="هزینه کشت ریحان با نوار تیپ در هکتار - تصویر 1"/><figcaption>Арзиши ҳаректари ҳосили лаванд бо ларзи drip tape</figcaption></figure><h3>Арзиши энергия ва об</h3><p>Лаванд набакист, ки ба оғозкунии сермилан илова менависад. Бо истифода аз ларзи тиқ, истифодаи об ба ҳадди ақал мерасад, аммо арзиши пойгонии об боз ҳам мавҷуд аст. Арзиши барқ ё газ барои помпаҳо қисме аз арзиши кишт кардани лаванд бо ларзи тиқ дар ҳаректарро ташкил медиҳад. Беҳтарсозии система бо танзими фишори мувофиқ ба кам кардани арзиши энергия кӯмак мекунад.</p><h2>Нуқтаҳои амалӣ барои беҳтарсозии арзиш ва самараноки</h2><p>Танҳо хариди андозҳои муосир кофӣ нест; идоракунии дуруст дар тӯли сикли рушди лаванд муайянкунандаи фоидаи ниҳоии шумост. Дар пай овардани нуқтаҳои калидии муҳимро таҳқиқ мекунем:</p><h3>Фосилагузории мувофиқ</h3><p>Фосилаи сафҳо ва нармаштҳо ба миқдори пӯшиши ларзи тиқ ва дастрасии нармашт ба об ва нури рӯзгир аст. Одатан фосилаи сафҳо 60 то 70 сантиметр ва фосилаи нохудиҳои нармашт 30 то 40 сантиметр барои лаванд мувофиқ аст. Ин фосилагузорӣ боиси он мешавад, ки ларзи тиқ дуруст бар рӯи решаҳои асосӣ ҷойгир шавад.</p><h3>Идоракунии заҳром ва гудронӣ</h3><p>Азбобки рафъи лента, ки эҳтимоли ғизо доданро (дуо-фидуинг) имконпазир мекунад, шумо метавонед мустақиман тавассути системаи обёрӣ, ҳариди кимиёвиро ба решаҳо расонад. Ин кор харҷи интиқол ва тақсимоти дастиро бартараф мекунад ва ба беҳтаршавии ҷалби моддаҳои ғизоӣ мусоядат мекунад. Диққат дод, ки концентрацияи баланди ҳариди метавонад боиси баста шудани рафъи лента гардад, бинобар ин аз филтрҳои мувофиқ истифода баред.</p><h3>Контроли бемориҳо ва узумҳои зараровар</h3><p>Райҳан ба бемориҳои қалавмонӣ ҳассос аст. Обёрӣ бо рафъи лента, агар сабаби хушк мондани сатҳи хок, ба камшавии пайдоиши бемориҳои баргҳо мусоядат мекунад. Аммо, узумҳои зараровар метавонанд манбаъҳои ғизои райҳанро бартараф созанд. Коркарди ҳашорот ва маљчпашӣ дар баробари истифода аз рафъи лента, харҷҳои идоракунии узумҳои зарароварро ба таври кӯҳш мекунанд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/هزینه-کشت-ریحان-با-نوار-تیپ-در-هکتار-کاربرد-عملی.webp" alt="هزینه کشت ریحان با نوار تیپ در هکتار - تصویر 2"/><figcaption>crop cost per hectare drip tape райҳан</figcaption></figure><h3>Мутақобила бо дигар корҳо</h3><p>Агар бағалҳои омехта дошта бошед, донистани харҷи бехҳои дигар маҳсулҳо барои фаҳмиши беҳтари қобилияти васеъшавии сармоӣ кӯмаккунанда аст. Барои мисол, равонакӣ <a href="https://navar-abyari.ir/cucumber-seed-per-hectare-guide/">миқдори бехи хурмо дар гектар</a> намоиш медиҳад, ки зичии кор кардани хурмо аз райҳан фарқ мекунад ва ниёзҳои обёрии ҳар як бояд ҷудо-ҷудо идора шаванд.</p><h3>Заробидан ва нигоҳдорӣ</h3><p>Осу баръади заробиданро чен мекунад. Аввалин заробиданҳо одатан бештар мешаванд. Масраҳи қувваи корӣ барои заробидани дастӣ қисми калонро ташкил медиҳад. Омӯзиши кормандон дар бораи тарзи дурусти чинидан метавонад тозагӣ ва бақоёфии маҳсулотро дар бозор баланд бардорад.</p><h2>Муқоисаи иқтисодӣ бо кӯҳпечашҳо</h2><p>Барои дидани намои умумии содироти иқтисодии осу нисбат ба дигар сабзавот, метавонам ба баррасии <a href="https://navar-abyari.ir/%D9%85%DB%8C%D8%B2%D8%A7%D9%86-%D8%A8%D8%B1%D8%AF%D8%A7%D8%B4%D8%AA-%D9%85%D8%A7%D8%B4-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/">миқдори заробидани машар дар гектар</a> ишора кунам. Машар низ ба эҳтироми вақти кӯҳпечандӣ ва заробидан ниёз дорад, амма содироти иқтисодии осу бо сабаби нархи баланд дар бозори кушодани хурдӣ ва барориш, одатан ҷозибагиртар аст. Инчунин, агар ба кӯҳпечии сабзавоти решагӣ даъоат дошта бошед, метавонед дархости муфассалро <a href="https://navar-abyari.ir/%d9%86%d9%88%d8%a7%d8%b1-%d8%aa%db%8c%d9%be-%d8%b4%d9%84%d8%ba%d9%85/">ниҳолпечии редиски</a> баррасӣ кунед, то фарқияти тахассусии обӣи ин ду гиёҳро фаҳмед.</p><h2>Саволҳои маъмул (FAQ)</h2><h3>1. Оё нӯри чангӣ барои тулӯн беҳтар аз системаи қатрагорӣ аст?</h3><p>Бале, нӯри чангӣ барои тулӯн аз сабаби хараҷи худи коркард ва ҳосилгирии зуд дар охири фасли бароришӣ беҳтар аст. Системаи қатрагорӣ, бо вуҷуди дақиқии баланд, хараҷи баланди овардани бозор дорад ва барои гиёҳоне, ба монанди тулӯн, ки давраи рушди кӯтоҳ доранд, метавонад фаъолияти иқтисодии паст доранд, агар нашуст зиёда аз як сол бошад.</p><h3>2. Чӣ тавр аз баставии нӯри чангӣ ҳангоми парҳези моддаҳо пешгирӣ карда мешавад?</h3><p>Истифодаи филтрҳои чӯғ бо зираҳои майда, лабикории маҳлули моддаҳо барои равшан кардани чангҳои маҳлулшуда ва истифодаи моддаҳои сифатнок ва тамоман маҳлулшуда, роҳҳои асосии пешгирӣ аз баставии нӯри чангӣ мебошанд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/هزینه-کشت-ریحان-با-نوار-تیپ-در-هکتار-جزئیات-فنی.webp" alt="هزینه کشت ریحان با نوار تیپ در هکتار - تصویر 3"/><figcaption>crop cost per hectare drip tape тулӯн</figcaption></figure><h3>3. Давраи умедҳои максималии нӯри чангӣ чӣ қадар аст?</h3><p>Бояд барои гуногунии филми пластикӣ, нури офтоб ва моҳияти истифода, нӯри чангҳои сифатнок одатан барои 2 то 3 фасли шустон давом меоварад. Истифодаи бозорҳои ба нури офтоб беҳтоз кардашуда метавонад ин умри бозро зиёд кунад.</p><h2>Хулоса ва стратегияҳои охирон</h2><p>Ҳисоббарорӣ <strong>Ҳармаи паҳлосии шафтолон бо лентаи пурқувват дар як гектар</strong> Ин як раванди динамикӣ аст, ки ба тағйирёбандаҳои маҳаллӣ, нархи умумии моддаҳои ашёи хом ва ҳарҷаи меҳнат вобаста аст. Бо вуҷуди ин, барои муваффақияти шумо нуқтаҳои зерин тавсия мешаванд:</p><ol><li><strong>Таҷҳизоти сифатнок:</strong> Харидани лентаи пурқувват аз брендҳои эътимодноки бо қаллоқии мувофиқ (монанди он ки дар <a href="https://navar-abyari.ir/ideal-wall-thickness-drip-tape-irrigation/">радифи қаллоқии девор</a> шарҳ дода шудааст) сармоягузории бемаҳол аст.</li><li><strong>Идоракунии обод ва код:</strong> Истифодаи системаи дуғфидинг барои баланд бардоштани сифат ва кам кардани хароҷоти дастӣ.</li><li><strong>Арзёши маҳсулот:</strong> Диаҳарҷаи андозаҳои чандмоҳавӣ барои максимум кардани даромад аз ҳар гектар.</li></ol><p>Бо назардошти қиммати иловаии растани чаро, истифодаи технологияи обёрӣи навори чип на танҳо усули муҳendisии кишоварзӣ, балки стратегияи иқтисодии ғаҷранак барои ҳар кишоварзи муосир мебошад. Агар шумо ба маълумоти бештар дар бораи кучи рӯнамунаҳои дигар ниёз дошта бошед, равонаи <a href="https://navar-abyari.ir/okra-yield-per-hectare-iraq/">Арзёши нақили нуб дар гектар</a> ҳам метавонад манбаи фойдеманд барои муқоиса бошад.</p><p>Умедворем, ки ин равона ба шумо кӯмак кард, то тасвири равшан аз хароҷот ва муфодҳои кучи чаро бо навори чип дошта бошед. Дар сурати зарурати маслиҳатҳои махсустар, ҳамеша бо олимони кишоварзии маҳаллии худ маслиҳат кунед, то дар асоси шароитҳои иқлимии минтақаи шумо қарорҳои беҳтар гиред.</p>','Тархи ҷамъоварии риҳон бо намуди тиб дар ҳектар: Раҳнамои куллӣ ва амалӣ','Рихан яке аз гиёҳҳои доруӣ буда, ки бо истифода аз технологияи сабзкардани хатӣ (nari tip), фоиданокӣ ва самаранокии он чанд бар афзуда мешавад. Дар ин роҳнамои комплексӣ мо ҳамаи ҷанбаҳои ҳарозукиҳои кундуки риханро бо хати сабз дар як гектар аз марҳилаҳои ибтидоӣ то ғалатҳои ниҳоӣ таҳлил мекунем, то ки шумо бо боварӣ сармоягузорӣ кунед.','publish','closed','closed','cost-of-basil-tib-planting-per-hectare-guide',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
