INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_title','دليل التكلفة: زراعة القطن بالري بالتنقيط للفدان في العراق' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_title');
INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','اكتشف التكلفة الكاملة لزراعة القطن بنظام الري بالتنقيط (نوار تيب) للفدان. دليل شامل يجمع بين الجانب الاقتصادي والفني المصمم خصيصاً للفلاحين العراقيين.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
