INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','Дар ин мақола ба саволи муҳим дар бораи миқдори зарури тоҷи марғиб дар як гектар барои кӯмакшавӣ бо усули обёркунии қатрагонӣ ва навбатии типӣ ҷавоб дода мешавад. Бо истифода аз ҷадвалҳо ва мисолҳои амалӣ, мефавҳем, ки чӣ тавр метавон миқдори зарури тоҷро муайян кард, бо назардошти шартҳои муттахид ва маъруфон. Ин рӯшноиноми комил барои чорвонҳо ва ҳосилнокшавандаҳо дар саросими кишвар мувофиқ аст.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
