INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддима дар бораи аҳамияти дақиқӣ дар кӯтоҳ кардани меваҳои хурмо</h2>\n<p>Муайянсозии дақиқ <strong>Миқдори тоҷи хурмо дар гектар</strong> Ин яке аз қадамҳои калидии муваффақият дар кӯтоҳ кардани ин маҳсулот аст. Интихоби тоҷи сифатнок, риояи принсипҳои масофагузорӣ ва мутобиқ будан бо системаи обдорӣ, бевосита ба ҳосилнокии ниҳоӣ ва сифати меваҳо таъсир мерасонад. Бисёр кишоварзон аз сабаби нодониши андозаи мувофиқ, бо зичии зиёди набототҳо ва беҳуда сарфи манбаъҳои об рӯбарӯ мешаванд. Дар ин раҳнамоя, мо ба таҳлил дар бораи ҷузъиёти фаннии кӯтоҳ кардани хурмо бо истифода аз системаи нӯрипӣ ва торӣ (қатораи каппат) мепардозем, то ки шумо бо боварии бештар ба кӯтоҳ кардани худ машғул шавед.</p>\n\n<p>Дар солҳои охир, бо пуршавии кӯтоҳ кардани саноатӣ ва истифода аз технологҳои нав, назар ба кӯтоҳ кардани хурмо тағйир ёфтааст. Интихоби тоҷро танҳо ба замин парсонда, интизор шудан кофӣ нест. идоракунии дақиқи давраи истеҳсолот, аз лаҳзаи интихоби тоҷ то кӯтоҳ кардани ниҳоӣ, нақши муҳиме дар кам кардани хароҷот ва зиёд кардани самаранокӣ дорад. Дар байни инҳо, тағйирёбандаи тоҷ ҳамчун оғозкунандаи давра, аҳамияти ду баробар ёфтааст. Агар дар муайян кардани миқдори тоҷ хато кунед, тамоми занҷири истеҳсолот ба таҳриш меояд ва хароҷоти иловагӣ, ба монанди истифодаи одаг, моддаҳои заҳрнок ва кори дастӣ низ зиёд мешавад. Бинобар ин, дониши амиқ дар бораи алоқа байни зичии буттаҳо ва манбаъҳои дастрас, малакаи зарури барои ҳар як кишоварзони муосир ҳисоб мешавад.</p>\n\n<h2>Ҳисобкунии стандартҳои кӯтоҳ кардани ва масофагузорӣ</h2>\n<h3>Масофаи мувофиқ байни қаторҳо ва дар дохили қатор</h3>\n<p>Барои ба даст овардани беҳтарин <strong>Миқдори бӯри хурмо дар хектар</strong>, аввал бояд андозаи сатҳҳоро муайян кунем. Одатан масораи байни сатҳҳо барои хурмоҳои нимоз 150 то 180 сантиметр ва масораи дар сатҳ байни 60 то 80 сантиметр тавсия дода мешавад. Агар масораи дар сатҳ аз 50 сантиметр камтар бошад, рақобат байни растанӣҳо зиёд мешавад ва сояфкунӣ боиси кам шудани рушноии бар меваҳо мегардад, ки ба интиқоли дониши кам ва зиёдшавии намнокӣ ва дар натиҷа бемории қамарӣ мусоидат мекунад.</p>\n<ul>\n<li>Масораи байни сатҳҳо: 150 то 180 сантиметр</li>\n<li>Масораи дар сатҳ: 60 то 80 сантиметр</li>\n<li>Шумораи бутонҳо дар хектар: тақрибан 1200 то 1400 бутон</li>\n</ul>\n<p>Бо фарз кардани зичии 1300 бутон дар як хектар ва донистани фоизи ғӯтишудагии бӯр (ки барои хурмо одатан байни 75 то 85 фоиз тағйир меёбад), миқдори бӯри лозима метавон ҳисоб кард. Барои намуна, агар бӯри шумо 50 дона дар 100 грамм бошад, ҳисобкуниҳо нишон медиҳанд, ки шумо ба тақрибан 250 то 300 грамм бӯри тоза барои ҳар хектар ниёз доред. Албатта, ин рақамҳо вобаста ба намуди нависҳои гибридӣ ва тоза фарқ мекунанд ва ҳамеша тавсия дода мешавад, ки аз маълумотҳои хати бӯр истифода баред.</p>\n\n<p>Як нуқтаи муҳим, ки бояд ба назар гирифт, намуди нависҳои коркардашуда мебошад. Нависҳои партобиш одатан ба зичии камтар ва масораи кушодашуда ниёз доранд, дар ҳоле ки нависҳои меваи хурднок метавонанд имконияти зичии бештарро диҳанд. Инчунин, намуди хок замин ба чуқурии бӯр ва дар натиҷа ба ниёз ба ислоҳоти баъдӣ таъсир мерасонад. Дар хокҳои рӯйи, ба сабаби ҷараёни зуд, эҳтимолан лозим аст, ки чуқурии бӯр каме бештар бошад, то намнокӣ дар атрофи бӯр нигоҳ дошта шавад. Ин тағйироти хурд, бевосита ба шумораи ниҳоии бутонҳои солим пас аз ғӯт шудан таъсир мерасонанд ва бояд ҳангоми ҳисоби ниҳоии миқдори бӯр ба назар гирифта шаванд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-طالبی-در-هکتار-راهنمای-جامع-تصویر-شاخص.webp" alt="مقدار بذر طالبی در هکتار: راهنمای جامع - تصویر 1"/><figcaption>миқдори бӯр дар хектар кишт хурмо</figcaption></figure>\n\n<h2>Нақши системаҳои оросиши полосагӣ ва чуқурин дар идоракунии тохм</h2>\n<h3>Мутобиқ кардани кишоварӣ ва оросиш</h3>\n<p>Истиносудани системаҳои оросиши нави тоҷоманн, ба монанди оросиши полосагӣ, имконият фароҳам меорад, ки паррандаҳоро дутоӣ ё ягона парвариш намоед. Дар оросиши полосагӣ об танҳо дар минтакаи решаҳои гиёҳ (минтакаи решаҳо) рехтиш мекунад. Ин боиси он мегардад, ки шумо тавонед бе нигаронӣ аз фишори об ё намакиӣ, зичии мувофиқро риоя кунед. Агар бо оросиши анъанавии кушод кор кунед, барои ҷуброни беъафкории об, метавонед маҷбур шавед, ки фосилаҳоро зиёдтар кунед, ки ба кам шудани ҳосили дар воҳиди сатҳ оварда мерасонад.</p>\n\n<p>Барои фоидавариш аз ин системаҳо, дониши принсипҳои техникии оросиши полосагӣ зарур аст. намудҳои гуногуни оросиши полосагӣ ҳар кадоме истифодаи худ доранд; масалан, полосаҳои ягона лӯла бо фосилаи 6 ё 10 сантиметрӣ барои паррандаҳои ҳассос ба намнокӣ мувофиқтаранд. Инчунин, <a href="https://navar-abyari.ir/%D9%86%D9%88%D8%A7%D8%B1-%D8%AA%DB%8C%D9%BE-%D9%81%D9%84%D9%81%D9%84/">Оросиши полосагӣ барои медуза</a> ва дигар маҳсулоти монанд, сохтори монанди медузаро доранд ва фаҳмидани он метавонад кӯмакрасон бошад. Дар системаҳои чуқурин, оромиши оқеб боиси он мегардад, ки афзоиши решаҳо дар чуқурии мувофиқ иборат шавад ва аз вобурнии решаҳо дар сатҳ пешгирӣ карда шавад. Ин хосият, махсусан дар минтақаҳое, ки тобоварии гиёҳ ба фишорҳои муҳитӣ паст аст, ҳаётан муҳим аст.</p>\n\n<h3>Нақшакунии оросиш дар асоси марҳилаи афзоиш</h3>\n<p>Намунаи обдиҳӣ ба медуза дар марҳилаҳои гуногун фарқ мекунад. Дар марҳилаи пайдоиш, намнокӣ баланд вале бе обгирӣ зарур аст. Дар марҳилаи гулкушодан ва мевоварӣ, фишори сабуки об метавонад ба беҳбудӣ ба ширинии мева кӯмак кунад. Барои танзими дақиқи обдиҳӣ, омӯзиш <a href="https://navar-abyari.ir/important-tips-drip-tape-irrigation/">Нуқтаҳои муҳим дар обёрӣ бо усули нӯрӣ-тақсимотӣ</a> Тавсия мегардад, ки аз зиёни оби обёрӣ ва нобаробарии ноумум ҳазар кунед. Дар минбаҳои хушк, истифодаи навъҳои гуногуни обёрӣ бо усули қаъқадар бо фосилаҳои бешаронок, метавонад хароҷотҳои энергия ва сармоягузориро кам намояд.</p>\n\n<p>Дар ин марҳила идоракунии фишори об ва самаранокии қаъқадарҳо низ муҳим аст. Гузашта набудани қаъқадарҳо метавонад боиси вуқӯи шӯрҳои маҳаллӣ ё обшӯршавӣ гардад, ки барои ришакҳои ҳассоси кӯҳан хатарнок аст. Истифодаи филтрҳои мувофиқ ва шустушуи мунтазими латифаҳо аз принсипҳои асосии нигоҳдоҳии саломатии системаи обёрӣ мебошад. Ҳамчунин, мувофиқати байни вақти обёрӣ ва рӯшноии офтоб метавонад самаранокии истифодаи обро баланд барад. Обёрӣ дар соатҳои хунуки рӯз, табури беҳамвор аз рӯи хаворо кам мекунад ва боиси меояд, ки оби бештар ба чуқури нӯҳҳароки ришакдор расонад. Ин нуқтаҳои нозук, вақте ки бо ҳисобҳои дақиқи миқдори тоҷдорӣ омехта карда мешаванд, як системаи мутаносибро ба вуҷуд меоранд, ки дар он ҳар қаъқади об ва ҳар грам тоҷдорӣ самаранокии беҳтарини худро татбиқ мекунанд.</p>\n\n<h2>Нуқтаҳои амалӣ барои баланд бардоштани максималии ҳосил дар воҳиди масоҳат</h2>\n<h3>Идоракунии зичӣ ва кӯркуштон</h3>\n<p>Яке аз хатогиҳои маъмул зиёд кардани тоҷдорӣ мебошад. Вақте шумораи ниҳолҳо аз ҳади муносиб (барои намуна 1400 ниҳол дар гектар) зиёд шавад, нафаскашии баргҳо кам мешавад ва рӯшноии кофӣ ба меваҳои дохилӣ намерасад. Дар ин шароит, шумо ба кӯркуштони шиддатнок ниёз доред, ки хароҷотҳои кор-рӯзро зиёд мекунад. Бинобар ин, аз оғоз <strong>Миқдори тоҷдори кӯҳан дар гектар</strong> ро вобаста ба фоизи воқеии хомешавии тоҷдор муайян кунед.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-طالبی-در-هکتار-راهنمای-جامع-کاربرد-عملی.webp" alt="مقدار بذر طالبی در هکتار: راهنمای جامع - تصویر 2"/><figcaption>Нируғи бех бошад ба гектар барои чаргоҳ (табоби) Ҳофтури</figcaption></figure>\n\n<p>Кӯрпаи охирин пас аз намоиш пайдо кардани буни сабз, марҳалаи ҳосилнок аст. Пайкар кардани гиёҳҳои заифтар ва мондани гиёҳҳои беҳтар, боиси мусоидат ба бутони асосӣ ва зиёдшавии андозаи мева мегардад. Ин корро бояд дар вақти мувофиқ ва бо эҳтиёт иҷро кард, то ба решаҳои боқимонда зарар нарасонад. Агар зичӣ аз ҳад зиёд бошад, ҳатто бо кӯрпа низ намерасад, ки фазои холиро пурра ислоҳ кард ва рақобат барои ғизо ва нур идома меёбад. Ин масъала махсусан дар чаргоҳҳои бисёр, ки дар онҳо фосилаи ибтидоӣ аз ҳадди идеалӣ камтар аст, муҳимтар аст. Бинобар ин, пешгӯӣ ва парҳез аз хатогиҳои ибтидоӣ дар бехкашӣ, нисбат ба ислоҳи онҳо пас аз муқаррар шудани гиёҳ хеле арзонтар аст.</p>\n\n<h3>Таъсири кунҷутро дар ҷӯбиш</h3>\n<p>Системаи қатрагирии ва тиллетири имконияти ғизо доданро пурра мекунад. Беҳтар аст, ки барномаи ғизои худро бо марҳалаи афзоиш танзим кунед. Дар марҳилаи рӯйиш, нитроген ва дар марҳилаи мевагиӣ, калий ва калсий муҳиманд. Барои намуна, дар чаргоҳҳои бехи ё ним-бех, истифода аз мақоми бумодӣ ва ислоҳотҳои техникӣ аҳамияти дугона меёбад. Санҷиши мақолаҳои монанд дар мавриди самараномо дар якҳаҳаҳои сатҳӣ, монанди <a href="https://navar-abyari.ir/asparagus-yield-per-hectare-guide/">Мулҳимати сипарк дар гектар</a> ё <a href="https://navar-abyari.ir/basil-harvest-yield-per-hectare-guide/">Самараномии раъӣш дар гектар</a> метавонад сари ғамҳои зиёдтари идоракунии зичиро дар маҳсулоти баргулӣ ва меваҳои хурд ба шумо диҳад.</p>\n\n<p>Интиқоли коҳоро тавассути системаи орошӣ бояд бо консентратсияи мувофиқ ва дар вақтҳои муайяни рӯз сурат гирад, то ки аз чашиндан ва хӯби шудани қатрапандҳо пешгирӣ шавад. Инчунин, pH-и маҳлули коҳорӣ бояд танзим гардад, то ки ҷабби реша ба мақсад расад. Дар ин раванд, ҳамкорӣ байни мутахассисони ғизоияти растанӣ ва муҳандисони орошӣ зарур аст. Ин шариқот сабб таъсири оптималии рушди растаниро фаровар менамояд, балки системаи орошӣ низ дар тӯли фасл бидуни осеб кор кунад. Диққат ба ин нуқта, ки ғизои реша ба воситаи бевосита ба сифати мева таъсир мерасонад, кӯҳконро ба муҳимии дақиқӣ дар ин қисм бештар таваҷҷуҳ медиҳад.</p>\n\n<h2>Саволҳои маъмул (FAQ)</h2>\n<h3>1. Беҳтарин вақти ниҳолнигории бодиби қандубӣ чӣ гоҳ аст?</h3>\n<p>Вобаста ба иқлим, одатан аз нимаи апрел то миёнаи май. Дар минтақаҳои гармтар метавонанд қаблтар ниҳоланданд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-طالبی-در-هکتار-راهنمای-جامع-جزئیات-فنی.webp" alt="مقدار بذر طالبی در هکتار: راهنمای جامع - تصویر 3"/><figcaption>Нисбати бодиби ҳосили қандубӣ барои як гектар</figcaption></figure>\n\n<h3>2. Оё ниҳолнигарии ҷуфтӣ дар таркишони ти́пӣ иҷозат дорад?</h3>\n<p>Бале, аммо бо риояи масофаи 50 сантиметр ва идоракунии дақиқи пуррарӣ барои пешгирӣ аз зичии зиёд.</p>\n\n\n<h3>3. Чӣ тавр аз бемориҳои реша дар ороиши қатравӣ пешгирӣ кунам?</h3>\n<p>Истифодаи кишти давравӣ, дезинфектсияи хок пеш аз кӯшоӣ ва нигоҳубинии филтрҳои системаи оварӣ бениҳоят муҳим аст.</p>\n\n<h2>Хулоса</h2>\n<p>Дақиқӣ дар <strong>Миқдори бӯни шарбат дар гектар</strong> Танҳо нимаш кор аст; нимаш, идоракунии ҷонбошии абрҳо ва ғизо аст. Бо истифода аз системаҳои набуни дуюн ва қатрӣ, шумо на танҳо маҳсулоти баробартари ҳосил меоваред, балки хароҷоти истеҳсолро низ паст меоред. ҳамеша аз нусхаҳои маҳаллӣ ё гибридҳо бо муқовимати баланд ба бемориҳо истифода баред ва шароити заминаи худро бо машварати мутахассисони маҳаллӣ мутобиқ кунед.</p>\n\n<p>Дар охир, муваффақият дар кишти шарбат ба як усули ҷамъӣ вобаста аст. Пайвастгарии дониши бӯн, фосилаҳо, оборӣ ва ғизо, калиди расидан ба фоидаи максималӣ аст. Коришони кишоварзӣ бояд дар ҳолати давомӣ дар бунёд будан бо техникаҳои нав бошанд, то аз боси мурақабати худ дар бозор нигоҳ дошт. Ин мақола танҳо як нуқтаи ибтидоя аст ва маъруф аст барои тафсилоти бештар, ба манбаҳои мутахассисонаи дастрас ва машварат бо мутахассисони маҳаллӣ равона кунед.</p>','Миқдори тухми кабудуи боғдорӣ дар гектар: дастурҳои умумӣ','Оё медонед, ки барои як гектар замин чӣ қадар нишонии хурма лозим аст? Дар ин мақола мо бартарии кишт, масофагузорӣ ва обёрӣ бо усули қутраро муҳкам муайян мекунем.','publish','closed','closed','miqdori-tuhmi-kabudui-botgori',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
