INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<p>Кашт ҷӯворӣ ба сифати яке аз муҳимтарин ҳаббҳо ғаламӣ ва инчунин яке ҳосили стратегӣ барои ордҳои чорвоӣ, ба идоракунии дақиқи захиравҳои обӣ ниёз дорад. Дар системаҳои обёрӣ полагӣ, <strong>Фасоли наворҳои тиб дар кашти ҷӯворӣ</strong> нақши ҳатмӣ дар тақсимоти баробари тар, рушди солим риштаҳо ва баҳсозии гирифтани моддаҳои ғизоӣ дорад. Интихоти нодурусти фасоли байни растрҳоя метавонад боиси фишобии об дар фазаи ҳассоси афзоиш ва ҳосилгирӣ шавад. Дар ин дастурамали ихтисосӣ, мо ба баррасии муҳандисӣ, физиология ва қоидаҳои амалӣ дар муайян кардани фасои мувофиқи навори тиб барои ҷӯворӣ мерасем.</p><h2>Асосҳои физиологии муайян кардани фасоли растрҳо дар ҷӯворӣ</h2><p>Ҷӯворӣ бобе бо риштаҳои васеъ ва чуқур аст, ки барои ноили шудан ба қудрати максималии рушд, ба фазои кофӣ барои паҳншавии уфуқӣ ва амудии риштаҳо ниёз дорад. Дар системаи навори тиб, ҳадафи асосӣ эҷоди «ҳалқаи шустанӣ» ё минтақаи таробнок будан аст, ки дақиқан бо системаи риштагии бобе ҳамчунӣ дошта бошад. Агар фасоли растрҳо (ва дар натиҷа фасои навороҳо) хеле кам бошад, рақобат байни дарахтонҳои ҳамсоя бар парвозҳо боиси паст шудани баландии бобе ва зиёд шудани фосилҳои эҳмосӣ мебошад. Аз ҷониби дигар, агар фасоли зиёд бошад, қисмҳое аз хок дар ҳолати рушди риштаҳо хушк мемонад ва самаранокии истифодаи об кам мегардад. Бар ин сабаб, <a href="https://navar-abyari.ir/%D9%87%D9%85%D9%87-%DA%86%DB%8C%D8%B2-%D8%AF%D8%B1%D8%A8%D8%A7%D8%B1%D9%87-%D9%85%D8%B2%D8%A7%DB%8C%D8%A7%DB%8C-%D9%86%D9%88%D8%A7%D8%B1-%D8%AA%DB%8C%D9%BE-%D9%BE%D9%84%D8%A7%DA%A9%D8%AF%D8%A7%D8%B1/">Ҳама чиз дар бораи фоидаҳои навори тиб намоишӣ</a> бар сифати хок ва баробарии обёрӣ, асоси ин танзимот аст.</p><h3>Таъсири зиёдшавӣ ба фасои тиб</h3><p>Яке аз параметрҳои асосӣ, ки ба таври мустақим бо фосилаи лампаи нафк пайванд дорад, зичии ноҳияҳо дар ҳектар аст. Дар климатҳои гуногун зичии тавсияшудаи ҷӯ отуб аз 45000 то 60000 ноҳия дар ҳектар тағйир меёбад. Ҳар чӣ зичӣ баландтар бошад, фосилаи байни қаторҳо бояд тараққоттар интихоб шавад, то ки пошии решаҳо оптималӣ бошад. Аммо фаромӯш кардан мумкин нест, ки зичии баланд ба идоракунии дақиқтари тарроҳии растаниҳо лозим аст. Барои фаҳмиши беҳтари робитаи байни тағйирёбандаҳои дигар, ба монанди бодирка ва обкорӣ, шумо метавонед дастурамузҳои ҷамъбасти дараҷаи баландро <a href="https://navar-abyari.ir/%d9%85%d9%82%d8%af%d8%a7%d8%b1-%d8%a8%d8%b0%d8%b1-%d8%b7%d8%a7%d9%84%d8%a8%db%8c-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">Миқдори бодиркаи сабзӣ дар ҳектар</a> матлаб кунед, то намунаҳои монанди идоракунии зичӣ дар сабзавотҳоро фаҳмёнд.</p><h2>Стандартҳои андоза ва фосилаҳои тавсияшуда</h2><p>Дар асоси тадқиқоти зиёда дар самтҳои гуногун, фосилаҳои стандартии лампаи нафк барои ҷӯ отуб одатан барои қаторҳои ягона байни 50 то 60 сантиметр ва барои қаторҳои дунафка (тапп) байни 90 то 110 сантиметр истифода мешаванд. Ин рақамҳо доимӣ нестанд ва бояд дар асоси чуқурии зерзул, навъи хок ва ҳарорати минтақа танзим шаванд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-ذرت-استانداردهای-توصیهشده-تصویر-شاخص.webp" alt="فاصله نوار تیپ در کشت ذرت: استانداردهای توصیه‌شده - تصویر 1"/><figcaption>drip tape spacing row layout crop ҷӯ отуб</figcaption></figure><table><thead><tr><th>Навъи ҷойгиршавӣ</th><th>Фосилаи лампаи нафк (сантиметр)</th><th>Фосила байни қаторҳо (сантиметр)</th><th>Тавсияи махсус</th></tr></thead><tbody><tr><td>Қаторҳои ягона (One row)</td><td>50 - 55</td><td>60 - 70</td><td>Мусоид барои хокҳои сабуқ ва зичии миёнаи навдаҳо</td></tr><tr><td>Қаторҳои дугона (Two row)</td><td>100 - 110</td><td>120 - 130</td><td>Мусоид барои хокҳои вазнин ва зичии баланди навдаҳо</td></tr><tr><td>Таркибӣ (маҷмӯа)</td><td>Тағирёбанда</td><td>Мутабо</td><td>Мувофиқат бо системаи помпа ва фишори корӣ</td></tr></tbody></table><p><strong>Нуқтаи калидӣ:</strong> Фосилаи нохуди лентаву аз маркази саф то фосилаи байни ду нохур набояд камтар аз нисфи чуқури зероб бошад, то ҳалқабҳои шустушӯ ҳампушӣи уфуқӣ наёбанд ва сабабкунандаи гӯрбандии решаҳо набошанд.</p><h2>Таъсири қалдовагӣ ва диаметри сӯрохии лентаву ба фосилагӣ</h2><p>Муайян кардани фосилаи лентаву дар киштҳои буқта бе ба назар гирифтани хосиятҳои техникии лента нопуроста аст. Диаметри сӯрохиҳои лента (масалан, 2 миллиметр барои лентаҳои фишорпаст) муайянкунандаи зичии қатрашавӣ (Flow Rate) мебошад. Дар буқта, ки ниёзи рӯзонаи обӣ мутабоғӣ дорад, лентаҳо бо дараҷаи баланди ҷараён (High Flow Rate) имкон медиҳанд, ки фосилаи байни нохурҳоро каме зиёд кунед, зеро шустушӯ тезтар ва чуқурии даромадан зиёдтар аст. Дар муқобил, лентаҳои кам-ҷараён ба фосилаҳои наздиктар ниёз доранд, то якгонагии пӯшиши намдор нигоҳ дошта шавад. Барои муқоиса бо дигар маҳсулотҳо, роҳнамоии оборӣ ба болғориҳо дар системаи лентаву, ки дар <a href="https://navar-abyari.ir/pepper-drip-tape-irrigation-guide/">pepper drip tape irrigation guide</a> тақдим шудааст, намунаи монанди танозуни мувозинати ҷараён ва фосиларо тақдим мекунад.</p><h3>Нуқтаҳои амалӣ ҳангоми насб кардан</h3><ul><li><strong>Сифатнокунӣ (таҷҳиз) замин:</strong> Пеш аз нигоҳ доштани система, сатҳи замин бояд пурраи мукаммал ва аз санҷи хурд берӯд, то ки фосилаҳои муайяншуда дар тӯли туннел ё зарра дар низоми дақиқ анҷом дода шаванд.</li><li><strong>Нигоҳ доштани система (типа):</strong> Рити (типа) бояд ба таври нигоҳ дошта шавад, ки сӯрохиҳои хурди он ба самти замин нигаронда шаванд, то аз пур шудан бо зарраҳои тафшун шуда барои омадашави онҳо ҳифз шаванд.</li><li><strong>Тафтишот фишор:</strong> Пеш аз кардани хонаи (кундушт), система-ро дар фишори корӣ (одатан 1 то 2 бар) санҷед, то аз паст шудани фишор дар охири нима (рити) омода шавед.</li></ul><h2>Офармоиш (беҳтаркунӣ) истифодаи об тавассути танзими фосилаи система (типа)</h2><p>Яке аз таъсирҳои асосии истифодаи фосилаи оптималӣ, кам шудани бухоршавӣ аз сатҳи замин аст. Вақте ки фосилаи рити (типа) дар кундушт задукир (гурех) зиёдтар аз ҳадди лозим бошад, қисмҳои калон замин дар ҳавои хушк ва гарм ҷазби бухоршавиро доранд. Бо нигоҳ доштани рити (типа) ба бадои (баҳраи) ё ҷойгир кардани он наздик ба реша (бо риоя кардани фосилаи бехатарӣ аз дарахти/шаха) ин талафоти ба ҳадди ақал расонида мешавад. Инчунин, дар системаҳои ритӣ (типа), идоракунии рафъ (масли) об ба самати табақаҳои амиқтар (Deep Percolation) муҳим аст. Агар фосилаи қаторҳо зиёд ва ҳаҷми оби рити (типа) кам бошад, об ба табақаҳои зерин замин ворид шуда ва решаҳо онро намегирянд. Аз ин рӯ, ) <strong>Мутобиқ кардани чуқурӣ дар зери об бо фосилаи safar</strong> Ибтидои қонуни аввали интиқолу абододӣ.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-ذرت-استانداردهای-توصیهشده-کاربرد-عملی.webp" alt="فاصله نوار تیپ در کشت ذرت: استانداردهای توصیه‌شده - تصویر 2"/><figcaption>drip tape spacing row layout crop ҷӯр</figcaption></figure><h3>Ташакули ба самаранӯми охирин</h3><p>Дар як тадқиқи ҳашарӣ, мушоҳида шуд, ки зиёдшавии фосилаи навори тири аз 50 то 60 сантиметр дар ҷӯрҳои зичивазъ, бо шароите, ки партовобияи кофӣ бошад, боиси зиёдшавии 5 то 8 фоизӣ дар вазни донҳо гардид. Ин афзоиши самаранӯмӣ асосан ба сабаби камшавии зарари дони дар решаҳо ва зиёдшавии ҳаҷми решаҳои фаъол аст. Барои муқоиса бо самаранӯмии ҷӯрҳои дигар дар системаи навори тири, шумо метавонед ба <a href="https://navar-abyari.ir/kudwa-natiq-iq-production-per-hectare-drip-tape/">kudwa natiq iq production per hectare drip tape</a> рӯй оред, ки маълумоти монанди таъсири обдорӣ ба самаранӯмӣ пешниҳод мекунад.</p><h2>Саволҳои маъмул (FAQ)</h2><h3>1. Оё фосилаи навори тири дар ҷӯр бояд доимӣ бошад ё тағйирёбанда?</h3><p>Фолаши (масофа) байни пӯшиҳо дар кукуҷӯ одатан доимӣ аст, вале бо тағйирот дар фазаи афзоиши бӯгоҳ метавон коэффисиентҳои аборӣ ва давомнокии обдориро тағйир дод. Аммо, тағйир додани фолаши физикӣ пӯши аз кӯмак (пас аз ниҳолӣ) имконнопазир аст ва бояд аз пеш бо назардошти зиёдтарин зичии ниҳоҳо муайян карда шавад.</p><h3>2. Дар хокҳои вазнин, масофа чанд сантиметр беҳтар аст?</h3><p>Дар хокҳои вазнин ва гулӣ гузаштагии об паст аст. Бинобар ин, истифодаи масофаҳои бароҳтро (масалан, 45 то 50 сантиметр барои қатори ягона) тавсия мекунад, то аз ба вуҷуд омадани давраҳои шуморкунандаи калон ва хушк байни пӯшиҳо пешгирӣ карда шавад. Инчунин, истифодаи пӯшиҳо бо диаметри сӯрохи калонтар дар ин хокҳо метавонад ба кам кардани вақти обдорӣ кӯмак кунад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-ذرت-استانداردهای-توصیهشده-جزئیات-فنی.webp" alt="فاصله نوار تیپ در کشت ذرت: استانداردهای توصیه‌شده - تصویر 3"/><figcaption>masofa-yi pishi-abori joygiri-qatori ankor kukujho</figcaption></figure><h3>3. Чӣ тавр аз пӯшидани сӯрохиҳои пӯши дар масофаҳои наздик пешгирӣ кунем?</h3><p>Истифодаи равонкунии мувофиқ дар вуруди система, шустушӯи мунтазами хатҳо пеш аз ниҳолӣ ва интихоби пӯшиҳо бо муқовимати баланд ба бӯгоҳҳои обӣ. Инчунин, агар масофаи пӯшии абории кукуҷӯ хеле наздик ба бадана бошад, дар ҳолати шустушӯи муносиб набудан метавонад ба фурӯравии дарахтор (сагс) оварда расонад; бинобар ин, ҳадди ақал 10 то 15 сантиметр масофаро аз ҷое, ки бӯдог доранда (ниҳо) ҷойгир карда мешавад, нигоҳ доред.</p><h2>Хулосаи охирин</h2><p>Интихоби масофаи шинаи чақиқ дар кӯмаки буғдой як қарорди чанд тағйирёфта аст, ки дар он таҳқиқи хак, зичии ҷӯлаҳо, ҳарорати минтақа ва хусусиятҳои чақиқро дар назар доранд. Рамкандани меъёрҳои 50 то 60 сантиметр барои пахшҳои якнафс ва 100 то 110 сантиметр барои пахшҳои дунимея нӯқти оғози хуб аст, аммо танзими нигаристон ба шароити ҷои парҳез кардан лозим аст. Бо беҳтар кардани ин масофа, шумо на танҳо пешгирӣ аз истифодаи зиёди об мекарда, балки асос барои афзоиши решаҳои қавитар ва дониҳои сифатнок созед. Барориш дар овардани об ба буғдой бо чақиқ лозим дорад, ки диққат ба тафсилоти техникӣ ва назорати даимии система гузоред, то мувофиқати пурраи байни об, хак ва наботат нигоҳ дошта шавад.</p>','Фосилаи тасдидашуда барои корсти кукутӯр: стандарти тавсияшуда ва нуқтаҳои иҷроӣ','Дар ин мақола, мо стандарти дақиқи масофаи қатори тупро дар карибозии шӯрбаро меомӯзем. Боварии кунед, ки чӣ тавр бо интихоби дурусти ҷойгиршавии қаторҳо ва кунҷи тупро, истифодабарии обро кам ва бартаровариро баланд бардоред.','publish','closed','closed','fosoil-tasdid-kukutor-standard-tavsiashuda',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
