INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_title','راهنمای مراقبت از عدس با نوار تیپ: نکات حیاتی برای کشاورزان عراقی' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_title');
INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','یاد بگیرید چگونه با استفاده از نوار تیپ (Tie-Tape) از لپه مراقبت کنید. این مقاله نکات کلیدی فنی و عملی برای افزایش بازدهی و کاهش هزینه‌ها در کشت لپه را به زبان ساده توضیح می‌دهد.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
