INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддима: Аҳамияти обории дақиқ дар боғзӯронҳои нукил</h2>\n<p>Нукил, ҳамчун яке аз муҳимтарин нӯкиҳо дар давраҳои кишоварӣ, ба идоракунии дақиқи захираҳои об ниёз дорад. Истифодаи системаи нӯкил (мағозаи нӯкил) бо сабаби таъсиси сарфнокунии об ва марказшавии моддаҳои ғизоӣ дар минтақаи реша, ивазгӯи мувофиқи обории анъанавӣ ва пахшшавӣ гардидааст. Ба вуҷуди ин, самаранокии ин система комилан ба <strong>нигоҳдорӣ ва пайдоиши давомноки нӯкил</strong> вобаста аст. Дар ин дастур мо равандҳои техникӣ ва оператсионии нигоҳдории нӯкилро, ки махсусан барои шароити киши нукил тарҳрезӣ шудаанд, баррасӣ мекунем. Мақсади асосии мо ин аст, ки бо пешниҳоди рӯйхатҳо (чеклистҳои) амалӣ, аз паст шудани тадриҷии фаъолияти гиёҳ ба сабаби вайроншавии техникӣи система пешгирӣ шавад. Нукил як гиёҳест, ки ҳассосияти баланд ба зарурати муҳитии дорад ва ҳар гуна коҳиш дар системаи оборӣ метавонад бевосита ба сифати дон ва самаранокии ниҳоӣ таъсир расонад. Бинобар ин, равиши нигоҳдорӣ бояд пешгӯиҳо гузорад, на ислоҳкунӣ. Кишоварон бояд донистанд, ки хароҷоти таъмиру иваз кардани нӯкили бидоракунда хеле баландтар аз хароҷоти вақтгириҳои кӯтоҳ барои сарбаскорӣ аст. Дар идома, сабабҳои физиологӣи ниёзи нукил ба шурӯрият баробари, мушкилоти техникӣ дар бораи басташавӣ ва зарбдории хокӣ ва роҳҳои пешрафта барои идоракунии ин масъалаҳоро бо мухтасари пурра шарҳ хоҳем дод. Ин мақола дар асоси таҷрибаҳои майдонӣ ва асосҳои муҳандисии оборӣ таҳия шудааст ва дастури умумӣ барои ҳамаи марҳилаҳои афрӯшиши нукил пешниҳод мекунад.</p>\n\n<h2>Чаро нукил ба нӯкил (мағозаи нӯкил) ниёз дорад?</h2>\n<p>Рӯшашакҳои лӯбиё дар ҳафтаҳои аввали афзоиш хеле нозук ва ҳассос ҳастанд ва барои тақсимоти баробари намии қабати сатҳии замин ниёз доранд. Оварии бастакӣ бо бориҳои кӯтоҳ ва миқдори кам оби оборӣ муҳити идеалиро барои нафаскашии рӯшашакҳо ба вуҷуд меоварад ва аз захобии рӯшашакҳо пешгирӣ мекунад. Ба муқобил, обориш пашшакӣ ё хаттӣ метавонад ба шӯи моддаҳои ғизоии замин дар атрофи наботот ва камшавии гузаронандагии қабати сатҳӣ оварда расонад. Инчунин, обориш хирӣ ё вазнин метавонад ба пайдоишии минтақаҳои обдор ва ғайриистидоршаванда оварда расонад, ки барои рӯшашакҳои лӯбиё маҳвгар буда метавонад. Барои дарки беҳтари параметрҳои техникӣ ва роҳи мувофиқ намудани оварии бастакӣ бо ниёзҳои рӯшашакҳо, омӯзиши манбаъҳои ихтисосӣ дар бораи самаранокии ин система тавсия мешавад. Дар лӯбиё, идоракунии дақиқи фосилаи байнисирифтӣ ва шумораи баромадҳо бар оварӣ беҳдошти якхелагии афзоиши буттаҳо ва имконияти охирини ҳосилро ба таври мустақим таъсир мерасонад. Оварии бастакӣ ба таври чунин тарҳрезӣ шудааст, ки обро дақиқан дар чуқурии рӯшашакҳои фаъол паҳн мекунад, аз талафоти об тавассути бухоршавии сатҳӣ пешгирӣ мекунад ва имконияти боргирии ҳамзамони чӯро (чӯрӣ)ро фароҳам меорад. Ин хусусиятҳо боиси он мешаванд, ки оварии бастакӣ на танҳо як асбоби оборӣ, балки системаи мукаммали идоракунии рӯшашакӣ бошад, ки ба назорати доимӣ ва парвариши маҳдудшуда ниёз дорад. Инчунин, вуҷуди оварии бастакӣ сабаби камшавии масоҳати заминии ҳаракаткунанда мешавад ва идоракунии зараррасонҳо ва бемориҳои заминро осон мекунад. Кишоварон бояд дарк кунанд, ки интихоби дарайв, фишори корӣ ва суръати ҷараён, унсурҳои асосии муваффақият дар кунуни лӯбиё мебошанд ва ҳар гуна диққатнадиҳӣ ба ин мавридҳо хароҷотҳои охиринро зиёд мекунад.</p>\n\n<h2>Нуқтаҳои калидии парвариши оварии бастакӣ дар марҳакаи кунуни лӯбиё</h2>\n<h3>1. Самарабарии баромадҳо ва назорати фишор</h3>\n<p>Интиқои қисман баромадҳои нӯри (лентаи) дарозӣ метавонад зуд боиси пайдо шудани минтақаҳои хушк дар қатори ҷанин бӯри шакарӣ гардад ва афзоиши якнавои растаниро вайрон намояд. Насб ва истифодаи дурусти нӯр (лентаи) дарозӣро таъмин мекунад, ки нӯр (лентаи) дуруст дар сазо гузошта шуда бо фишори мувофиқ кор кунад. Дар марҳилаҳои аввал ва миёнаи афзоиш, бояд фишори хати партобӣ ва хати дуделро дар якҷоягӣ муқоиса кунед, то ошкор кунед, ки фишор ба таври ғайриоддӣ паст омадааст. Паст шудани фишор беш аз 15 дарсад нисбат ба ҳолати аслӣ ошкории огоҳкунандаи вуҷуди афзоиши дохилӣ дар деворҳои нӯр (лентаи) мебошад, ки бояд фавран санҷида шавад. Инчунин, назорати ҳарорати об ва фишори корӣ бояд ҳаррӯза дар соатҳои қуллаи истеъмолиёт анҷом ёбад, то аз тағйироти имконияти доштани система пешгирӣ шавад. Тағйироти хурд дар ҳаҷми баромад метавонад ба зарарҳои физиологӣ дар растани бӯри шакарӣ таъсир расонад ва сифати маҳсулро паст орад. Кӯрбак бояд барои назорати фишор аз манометрҳои дақиқ истифода барад ва дар ҳолати мушоҳидашудани норамонӣ, системаро хомӯш карда сабабро муайян намояд. Ин роҳандози барои бехатар кардани система қадами аввал дар нигоҳдории дарозмуддати нӯр (лентаи) мебошад. Воқеан, фишори мувофиқ дилдиби ҳар як системаи обёрӣи қатраафкан аст ва бегоҳкорӣ ба он ҳамаи сармоягузории анҷом ёфда дар лоиҳаи бӯри шакариро ба хатар меандозад. Инчунин, санҷиши равонӣ аз пайвандҳо дар нуқтаҳои гуногуни роҳи нӯр (лентаи) баъзе аз ин боздид аст, ки набоист фаромӯш карда шавад.</p>\n\n<h3>2. Фильтратсияи пешгирии хомӯшӣ</h3>\n<p>Бӯри шакарӣ одатан дар хокҳои сангсор то слагистӣ шиною мебошад, ки ба дохил омадани зарраҳои сангсор ва моддаҳои илтимудор ба нӯр (лентаи) омадан доранд. Истифодаи фильтрҳои шабака бо маш 120 то 150 барои обёрӣи нӯр (лентаи) вазъиятӣ аст ва набоист аз назар барқадар шавад. Инчунин, шустани фильтр дар ҳар давраи обёрӣ, ки фишор паст мешавад, баъзе аз чеклиспи <strong>Нигоҳдории нӯр (лентаи) дарозӣ</strong> бояд муносиб ва бояд мунтазам анҷом шавад. Напокундагии тозагӣ боиси пайдо шудани нуқтаҳои нофаҳмо дар тағозуи решаҳои лӯбиӣ мешавад ва растаниро ба таҳаммули сахт меоряд. Фильтри мувофиқ, масалан филтри дискӣ ё филтри дукунӣ, бояд чунин насб карда шавад, ки даришавӣ ба он барои холӣ кардани ҷараёнҳо осон бошад. Истифодаи фильтри номувофиқ ё фарсода хатари бӯҳронии пӯшидогӣи намунаи сангинро бо шакли бомуфаззаф зиёд менамояд ва боиси вайронҳои васеъ мешавад. Тавсия мешавад, ки ду фильтр ҳамчун ҷуфт истифода шаванд, токи дар сурати лозим, яке шуста шавад ва дигараш иваз карда шавад, то давомнокии обёрӣ таъмин гардад. Ин роҳи амниятӣ, махсусан дар фаслҳои гарм, ки таҳаммул ба таҳаммули обии лӯбиӣ бештар аст, аҳамияти дукарата дорад. Ҳамчунин, санҷиши саломатии шабакаҳои фильтрация қисми барномаи нигоҳубини пешгӯиандозона аст, ки аз ворид шудани зарраҳои зараррасон ба дили система пешгирӣ мекунад. Ин қисми мақола бар аҳамияти ҳайтии фильтрация таъкид мекунад. Аз ин сабаб, омӯзиши дастурамали ихтисосӣ дар ин соҳа тавсия мешавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/نگهداری-لپه-با-نوار-تیپ-نکات-کلیدی-تصویر-شاخص.webp" alt="نگهداری لپه با نوار تیپ: نکات کلیدی - تصویر 1"/><figcaption>crop drip tape maintenance care лӯбиӣ</figcaption></figure>\n<a href="https://navar-abyari.ir/nori-tipa-kalmos-robnameyi-obyorii/">nori tipa kalmos robnameyi obyorii</a>\n\n<h3>3. Идоракунии фитопатогенҳо тавассути обёрӣ</h3>\n<p>Нобигӣ ба бемориҳои фумориз ва склерия ҳассос аст. Осуғонидан бо нӯқули каппакии (дривери) хокро хушк нигоҳ медорад, дар ҳоле ки минтақаи реша намнок аст; ин паҳншавии сиротҳои хокистариро кам мекунад ва муҳити рушди зангариҳоро маҳдуд месозад. Бо вуҷуди ин, агар намнокии нисбӣ дар атрофи кобилаи рӯёнун аз сабаби вобарии нӯқулҳои каппакӣ зиёд шавад, метавонад муҳити мусоид барои рушди патогенҳо фароҳам орад. Бинобар ин, танзими миқдори оби нӯқулҳои каппакӣ ба таври ки вобарии кобила рух надиҳад, як принсипи муҳим дар нигоҳубини система аст ва бояд бо диққат назорат карда шавад. Инчунин, истифодаи системаҳои кидериз (фитокдериз) тавассути нӯқулҳои каппакӣ метавонад пешгирии бемориҳоро мустаҳкам кунад. Бояд дигаронаи шумо бошад, ки намнокии зиёд дар минтақаи реша хатаршавии густариши реша ва зараровандаҳоро зиёд мекунад. Назорати масофаи нӯқул аз кобилаи рӯёнун ва пешгирии ҷамъшавии об дар косаҳо, аз ҷиҳати нозукият нигоҳубин аст, ки надоред фаромӯш кунед. Ин идоракунии ақлиноки намнокӣ, мувозинати нозук байни ниёзҳои обии нобигӣ ва хатари бемориро ба вуҷуд меорад. Кӯргандони муваффақ, онҳоян, ки ин мувозинатро нигоҳ медоранд ва намегзаронанд, ки системаи осуғонидан ба манбаи беморӣ табдил ёбад. Инчунин, назорати бинавии нокаҳои нобигӣ дар минтақаҳои гуногуни замин барои муайян кардани ирҳоҳои беморӣ дар ҳолати ибтидоӣ, калиди муваффақият дар ин қисмат аз нигоҳубин аст.</p>\n\n\n<h2>Ҷадвали ҷадвали санҷиши техникӣи нӯқулҳои каппакӣ</h2>\n<p>Барои таъмини умри фоидаи нӯқулҳои каппакӣ ва нигоҳдории фаъолияти он, бояд санҷишҳои мӯҳлалӣ ва мунтазам анҷом дода шаванд. Ҷадвали зерин рӯйхати таклифшудаи заминҳои нобигиро нишон медиҳад, ки бояд ҳамчун қисми нақшаи рӯзаона ё ҳафтагӣ иҷро гардад:</p>\n<table border="1">\n  <tr>\n    <th>Қисми система</th>\n    <th>Давомнокии санҷиш</th>\n    <th>Оператсияҳои лозимӣ</th>\n  </tr>\n  <tr>\n    <td>Обиҳои нӯқулҳои каппакӣ</td>\n    <td>Ҳар 3 рӯз</td>\n    <td>Санҷиши якхелагии ҷараёни об дар ҳамаи нуқтаҳо; шустани хуруҷҳои ним-пӯшида бо об дар фишори баланд</td>\n  </tr>\n  <tr>\n    <td>Филтри марказӣ</td>\n    <td>Ҳар 7 рӯз</td>\n    <td>Кушودани бунёд, шустани равшанҳо бо об ва санҷиши носозии физикӣ</td>\n  </tr>\n  <tr>\n    <td>Пайвастҳаҳои наноми (додел) ба лент</td>\n    <td>Ҳар ҳафта</td>\n    <td>Зӯрандани пайвастҳо, санҷиши нақдиӣ аз нуқтаҳои пайваст ва ислоҳи зарари физикӣ</td>\n  </tr>\n  <tr>\n    <td>Помпа ва манбаи таъминкунанда</td>\n    <td>моҳона</td>\n    <td>Танзими фишури пардохти помпа барои мувофиқат ба мушаххасномаҳои риштаи таминкунӣ</td>\n  </tr>\n</table>\n<p>РИЁСАНДИ ИҲВОСИ ИН ЖДВАЛ АСОСИ ТАЗОТУНИ СТАНДАРТӢРО ТАШКИЛ МЕКУНАД. НАМЭҲОРИДАН ба ИН ДАРҶОИ ЗАМОН, ба ҷамъшавии мушкилоти боида оварда мерасонад, ки ҳалли онҳо дар марҳилаҳои баъдӣ хеле душвортар ва қиматандозтар мешавад. Ҳамчунин, ба қайд кардани натиҷаҳои ҳар озмудиш дар ҳисобҳои техникӣи боғ ба назорати раванди кори система ва пешгӯии хатогиҳои оянда кӯмак мерасонад. Ин равиши муъайяншуда бо маълумот, нигоҳубини риштаи таминкунӣро аз як кори тахминӣ ба як раванди илмӣ табдил медиҳад.</p>\n\n<h2>Бартарӣ додани қабз ба риштаи таминкунӣ бо ғаҷ</h2>\n<p>Қабз ба риштаи таминкунӣ дар боғҳои ғаҷ одатан ба сабаби ҷамъ шудани оҳак ё қабзшавӣ бо моддаҳои аломӣ мебошад. Усулҳои кимиёвӣ чун ки хамиши лимонӣ, шустани хлор ё истифодаи хамиши ацетӣ метавонанд самаранок бошанд. Аммо интихоби дурусти хамшӣ бояд дар асоси сахтии обии маҳаллӣ ва намуди асосии ҷамъшавӣ амалӣ шавад. Ҳамчунин, дар ҳолати мушоҳида шудани халакҳои сабз-сархӯб дар ҷойҳои пардохт, нишонаи мушкили биологӣ аст, ки ба шустани шоки бо ҳалкунандаи хлор ё формалидӣ ниёз дорад. Раёнд кардани шустанӣ бо эҳтиёти кифоя анҷом дода шавад, то деворҳои ришта зарар надиҳад. Истифодаи ҳалкунандаи хамшӣ бо таъмини номувофиқ, метавонад ба риштаи полиэтиленӣ зарар расонад ва умри онро кӯтоҳ кунад. Ҳамчунин, парчасҳои ҷамъшуда, ки дар нуқтаҳои қабзшудаи система ҷамъ шудаанд, бояд ба таври механикӣ берун оварда шаванд, то ҷараёни об озод шавад. Дар ниҳоят, пас аз ҳар шустанӣ, фишори кории ришта бояд аз нав калибрезавӣ шавад, то дониши дуруст пардохтҳо таъмин гардад. Ин равандҳо бояд пешакӣ нақшаҷуфта шаванд ва дар ҳолати пайдо шудани мушкил, фавран амалӣ гарданд, то хатар ба риштаи ғаҳ аз ҳад зиёд кам шавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/نگهداری-لپه-با-نوار-تیپ-نکات-کلیدی-کاربرد-عملی.webp" alt="نگهداری لپه با نوار تیپ: نکات کلیدی - تصویر 2"/><figcaption>crop drip tape maintenance care ғаҷ</figcaption></figure>\n\n\n<h3>Нигоҳубини риштакорон дар бархӯрди тағйирёбии ҳарорат</h3>\n<p>Рӯзҳои чангҳо дар чуқурии камтар аз 20 сантиметр фаъоланд. Нӯри пичек бояд дақиқан дар ин сатҳ ҷойгир шавад, то ки обро мустақиман ба рӯзҳои фаъол расонад. Агар нӯри пичек дар чуқурии бештар ҷойгир шавад, рӯзҳои сатҳии чангҳо хушк шуда, рушд қатъ мешавад. Дар ҳифзи нӯри пичек бояд пас аз ҳар давраи обёрӣ, хоки атрофи растаниро санҷед, то таъмин карда шавад, ки минтақаи рӯзҳои фаъол намнок аст ва аз камбудии об наарзид. Барои муқоисаи кори бо дигар растаниҳои рӯздор, шумо метавонед <a href="https://navar-abyari.ir/%d8%b1%d9%88%d8%b4-%da%a9%d8%a7%d8%b4%d8%aa-%d9%be%db%8c%d8%a7%d8%b2-%d9%82%d8%b7%d8%b1%d9%87-%d8%a7%db%8c/">усули нишастани пиёзро бо пичек</a> ро низ баррасӣ кунед; зеро принсипҳои нигоҳдории намнокии рӯздор монанд аст, аммо ҳассосияти пиёз ба фитоҳамворандаҳои хоси хок бештар аст. Дар чанг, ин ҳассосият ба намнокҳои номуқаррарӣ боиси он мешавад, ки ҳатто тағйироти хурд дар ҳарорати хок таъсир мебарад. Бинобар ин, назорати намнокии хок ҳамчун параметри мустақил, ҷузъи риётии назорати нӯри пичек ҳисоб карда мешавад. Инчунин, танзими чуқурии нӯри пичек барои шароити гуногуни коркарди хок ба тафтиши мунтазам ниёз дорад.</p>\n\n<h2>Саволҳои маъмулӣ (FAQ)</h2>\n<h3>Оё нӯри пичеки чангҳоро дубора истифода бурдан мумкин аст?</h3>\n<p>Бале, агар нӯри пичек аз нӯи полиэтилен бо ғализии кофӣ бошад ва дар охири фаввара ба тартиб ҷамъ карда ва шусту омада шавад, дар фаввараи навбатист истифода бурдан мумкин аст. Аммо тавсия дода мешавад, ки пас аз ду то се сол, ба сабаби фарсудагии UV ва кам шудани дақиқияти баромадҳо, нӯри нав харидорӣ шавад. Нигоҳдори дуруст дар фаввараи нишастан, калиди зиёд кардани умри муносиби нӯр аст.</p>\n\n<h3>Беҳтарин вақти шусту омадани нӯри пичек дар чангҳо чӣ гоҳ аст?</h3>\n<p>Беҳтарин вақт, вақте аст, ки растании чангҳо ҳанӯз рӯзҳои зинда дар хок дорад ва метавонад аз моддаҳои шимиии зарариашои шусту омад зарар надид, ё пас аз ҳарифт вақте ки нӯр омода барои ҷамъ кардан аст. Шусту омад бояд бо ҳарорати баланди об ва фишори мувофиқ анҷом шавад, то ки араваҳо аз деворҳои нӯр берун шаванд. Ошомӣ дар ин марҳила метавонад ба нӯр зарар расонад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/نگهداری-لپه-با-نوار-تیپ-نکات-کلیدی-جزئیات-فنی.webp" alt="نگهداری لپه با نوار تیپ: نکات کلیدی - تصویر 3"/><figcaption>иҳоро ва парвариши лавзан барои анбори дрип лопе</figcaption></figure>\n\n<h3>Чӣ тавр аз зарари лопе ба система пешгирӣ кунем?</h3>\n<p>Бо риояи асосҳои техникаи насб, аз ворид шудани фишори намумкин ба лӯлаҳо ва баромадҳо пешгирӣ кунед. Инчунин, назорати намии хок маънои ин аст, ки решаи лопе бояд ҳамеша дар ҳудуди дилхоҳ нигоҳ дошта шавад ва аз зарари хушкӣ ё об хӯрдан пешгирӣ карда шавад.</p>\n\n\n<h2>Хулоса ва тавсияи охирин</h2>\n<p>Нигоҳубини анбори дрип раванди фаъол аст, на ғайрифаъол. Дар кариши лопе, дақиқ дар масофаҳои баромадҳо, тозагии филтрҳо ва назорати фишор, се станини асосӣ барои зиёд кардани ҳосил ва кам кардани истеъмоли обнокӣ мебошанд. Бо риояи ин нуқтаҳо, шумо ҳам метавонед аз саломати решаи лопе эҳтимол пардозед ва ҳам умри абзорҳои обнокӣ-и худро зиёд кунед. Барои дастрасӣ ба дониши чуқуртар дар бораи зичии бехорӣ ва таъсири он ба талаботи обнокӣ, омӯзиш <a href="https://navar-abyari.ir/quantity-beet-seeds-per-hectare-guide/">quantity beet seeds per hectare guide</a> метавонад фоидаовар бошад, зеро мантиқи идоракунии ангуштӣ ва решаҳои монанд аст. Дар охир, шиносӣ бо фоидаҳои ҳофизи ин система, анҷумани кофӣ барои таъаллук ба парваришро ба вуҷуд меорад. Фоидаҳои анбори обнокӣ-и дрип аз ҷуз сарфазидан дар об, аз ҷумла назорати арамҳои зараровар ва беҳбудӣ дар тақсимоти моддаҳои заҳрнок тавассути системаи обнокӣ низ мегардад. Бо иҷрои мунтазами барномаҳои нигоҳубин, инчори лопе-и шумо ҳамеша дар шароити беҳтарини намӣ вағизоӣ мемонанд ва имконияти коркарди ба максимум мерасад.</p>\n<p><strong>мавооди алоқаманд:</strong> <a href="https://navar-abyari.ir/%D9%86%D8%AD%D9%88%D9%87-%D8%A7%D9%81%D8%B2%D8%A7%DB%8C%D8%B4-%D8%B9%D9%85%D8%B1-%D9%85%D9%81%DB%8C%D8%AF-%D9%86%D9%88%D8%A7%D8%B1-%D8%AA%DB%8C%D9%BE/">D986D8ADD988D987 D8A7D981D8B2D8A7DB8CD8B4 D8B9D985D8B1 D985D981DB8CD8AF D986D988D8A7D8B1 D8AADB8CD9BE</a></p>','Дармонди соя бо намунаи T: Нуқтаҳои асосӣ','Кунҷи кунҷ ба фишори оби таъсирчанд аст. Ин мақола роҳнамоии ихтисосӣ барои парвариши дурусти банди нубататонро пешниҳод мекунад, то решаҳои кунҷ ба маблағи максималии обёрӣ расанд.','publish','closed','closed','damondi-soya-bo-namuna-i-t',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
