INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_title','دليل التكاليف الاقتصادية لزراعة الجوارش بطريقة الناقول في العراق' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_title');
INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','اكتشف تكلفة محصول الجوارش بنظام الناقول (Tep) لكل هكتار في العراق. دليل شامل للمزارعين العراقيين يغطي النفقات، العوائد، وكفاءة الري.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
