INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Мултимарофи арзиши парвариши бӯми (кунфу) бо ариёби нӯри (типе) дар ҳектар</h2><p>Бӯм яке аз молҳои стратегӣ дар кишоварии Эрон аст, ки талаби он дар бозорҳои хӯроквор ва саноатӣ (чун равған ва хӯроки чорво) меафзояд. Аммо масъалаи асосии деҳқонон идоракунии хароҷоти истеҳсол ва махсусан хароҷоти обёрӣ мебошад. Истинод аз ариёбии нӯри (Drip Tape) ҳамчун яке аз арзонтарин ва корангизтарин системаҳои ариёбии фишорпазир, имконияти идоракунии дақиқи манбаъҳои об ва кам кардани хароҷоти меҳнатро фароҳам меорад. Аммо бисёр истеҳсолкунандагон ҳанӯз <strong>Арзиши парвариши бӯм бо ариёбии нӯри дар ҳектар</strong> маълумотҳои дақиқи оморӣ надоранд ва нигаронанд, ки оё ин сармоягузории ибтидоӣ боиси сарфазамонеи давомдӯрӣ мешавад ё не. Дар ин мақолаи ихтисосӣ мо ҳамаи ҷанбаҳои иқтисодӣ, техникӣ ва амалӣ-амалии ин масъаларо баррасӣ мекунем, то шумо бо назари равшан ҳалли қарор гиред.</p><h3>Ҳамчунӣ таҳлили хароҷот ба ҳар ҳектар</h3><p>Барои ҳар як парвариши зироат, шиносоӣ бо сохтори хароҷотҳо ҳаётист. Дар системаҳои ариёбии анъанавӣ, хароҷоти помпакуӣ, дасткорӣ ва таърифи об хеле баланд аст. Аммо бо ҷорӣ сохтани ариёбии нӯри, хароҷоти амалиётӣ кам мешавад. Таҳлили дақиқи хароҷотҳо ба шумо кӯмак мекунад, ки нуқтаи баробаршавии хуруҷот ва хароҷот (Break-even point)ро дар солҳои ояндаи парвариш шиносасазед. Илова бар ин, донистани миқдори оби лозимӣ ба ҳар ҳектар дар парвариши бӯм, ба шумо дар барномасозии истифодаи манбаъҳои камоб кӯмак мекунад. Барои дарки беҳтари робита байни истифодаи об ва самаранӯмӣ, метавонед ба роҳнамои умумӣ <a href="https://navar-abyari.ir/%D9%85%D9%82%D8%AF%D8%A7%D8%B1-%D8%A8%D8%B0%D8%B1-%D8%AC%D9%88-%D8%A2%D8%A8%DB%8C-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/" title="مقدار آب مورد نیاز در هکتار">Миқдори оби лозимӣ дар ҳектар</a> муроҷиа кунед, ки мафҳумҳои асосиро шарҳ медиҳад.</p><h2>Қисмҳои асосии расонаҳои парвариши маҳви бо риштаи қатқома</h2><p>Расонаи умумии парвариши маҳви ба ду гурӯҳи собит ва тағйирёбанда тақсим мешавад. Дар қисми тағйирёбанда расонаи хариди риштаи қатқомаи бод, лӯлаи асосӣ, асбобҳо ва помпа нақши муҳим мебозад. Аммо нуқтаи муҳим тарзи истифода ва расонаи ивазкунии риштаи қатқома аст, ки бояд дар ҳисобкуниҳои чандсола дар назар дошта шавад. Дар зери инҳо, тафсилоти ҳар як қисмро баррасӣ мекунем.</p><h3>Расонаи системаи обёрӣ (риштаи қатқома ва шланги асосӣ)</h3><p>Расонаи системаи обёрӣ тавассути фишор қисми калоне аз сармои ибтидоиро ташкил медиҳад. Барои маҳви, одатан барои хатҳои асосӣ аз лӯлаҳои шлангӣ бо диамметрҳои 125 то 250 миллиметр истифода мебаранд ва риштаҳои қатқомаи мухталифро вобаста ба ҳаҷми обрасонӣ (мètre кубӣ дар соат) ва фосилаи қатқомаҳо насб мекунанд. Интихоби риштаи қатқомаи мувофиқ ба паҳши бӯри парвариши маҳви (одатан 60 то 80 сантиметр) ҳатмист. Шумо бояд расонаи хариди километри риштаи қатқомаро ба шуми гектарҳои заминаатон тақсим кунед, то расонаи барои ҳар гектар муайян шавад. Инчунин, расонаи насб ва корҳои дастӣ барои пайваст кардан ва тақсимоти риштаҳо низ аз ин қисм ҷудо намешавад. Агар аз сарчашмаҳои обёрсии сатҳӣ истифода баред, расонаи насбкунии помпа ва анбори захира низ бояд ҳамчун расонаи собит илова карда шавад. Барои дарк беҳтари тарзи дурустии фосилагузорӣ, ки ба расона ва дақиқии обёрӣ таъсир мерасонад, омода шудан ба мақолаи <a href="https://navar-abyari.ir/corn-drip-tape-spacing-forage-corn-guide/" title="راهنمای فاصله نوار تیپ ذرت خوراک">Дастураи фосилаи риштаи қатқомаи ҷӯсорӣ</a> тавсия карда мешавад, зеро принсипҳои техникӣ дар фароҳам овардани фосилаҳо дар набототҳои монанди маҳв то андозаи зиёд такроршавандаанд.</p><h3>Расонаи бод, корҳои дастӣ ва ибтидоӣ</h3><p>Нӯки ҷусҷум (навъи роҳ, навъҳои маҳаллӣ ё хориҷӣ) таъсири мустақим ба ҳосили ниҳоӣ ва дар натиҷа ба ROI (бардеҳии сармоя) меояд. Харҷоти ибтидоӣ, аз ҷумла шӯрдакунӣ, кашидани силосҳо ва паҳн кардани ҳашаракҷӯй низ дар ҳисобкунии харҷоти умумӣ шомиланд. Нуқтаи мусбат дар парвариши қатъиятӣ бо набуни (дип-тейп) камшавии ниёз ба ҳашаракҷӯйҳои гурӯҳбон аст, зеро пӯшиши муносиби хок ва камшавии рақобат дар заминаи навбун рақобатро коҳиш медеҳад. Ҳамин тавр, харҷоти озуҳои кимиёвӣ (нитроген, фосфор, калий) ҳамчун тағйирёбанда боқӣ мемонад. Истифодаи парвариш бо маҳлӯл бо системаи дип-тейп метавонад самаранокии ҷазби озуҳоро то 30 ваздият зиёд кунад, вале харҷоти ибтидии дастгоҳи озукуниро низ дар бар мегирад. Агар шумо бо ҳисобкунии бардеҳии маҳсулоти дигар, ба монанди картошка шинос бошед, метавонед аз <a href="https://navar-abyari.ir/mohdath-intaj-thur-maksikhi-li-l-hektar-daleel-shamil-lil-muzariin/" title="محصولات بازدهی بالا در هکتار">раҳнамоӣ оид ба маҳсулот бо бардеҳии баланд дар гектар</a> барои муқоисаи фоидаандозии ҷусҷум бо парваришҳои ивазкунанда истифода баред.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/هزینه-کشت-بامیه-با-نوار-تیپ-در-هکتار-تصویر-شاخص.webp" alt="هزینه کشت بامیه با نوار تیپ در هکتار - تصویر 1"/><figcaption>crop cost per hectare drip tape ҷусҷум</figcaption></figure><h2>Ҳисобкунии дақиқи истеъмоли об ва харҷоти энергия</h2><p>Яке аз муқобилатҳои асосии набуни (дип-тейп) коҳиши ҳисобкорандаи истифодаи об аст. Ҷусҷум ҳашаркаи торикранг аст, аммо дар марҳилаҳои ҳисобкунандаи расидашавӣ ва мевадиҳӣ ба обрасониши муқаррарӣ ниёз дорад. Ҳисобкунии ниёзи обии ҷусҷум барои ҳар гектар бояд асосан ба Kc (CROP COEFFICIENT) марҳилаҳои расидан, иқлими минтақа ва рутубати хок амал шавад. Дар иқлимоти хушки Эрон, одатан ниёзи умумии обии ҷусҷум аз 8000 то 12000 литр барои ҳар метри мураббаъ дар давоми мавсими расидан ҳисоб мешавад. Агар аз системаи дип-тейп бо самаранокии амалкунандаи 90 то 95 ваздият истифода баред, харҷоти помпагузорӣ (энергия) ба таври иловагӣ кам мешавад, зеро ҳаҷми камтари об ба ҳаракат овардан лозим аст. Инчунин, истифодаи помпаҳои барқии самаранок ва танзими шитоби дурусти система, аз харҷоти пинҳонӣ дар ҳисобҳои энергӣ пешгирӣ мекунад. Барои тафсилоти бештар дар бораи ҳисобкунии помпагузорӣ, ба <a href="https://navar-abyari.ir/%D9%85%D9%82%D8%AF%D8%A7%D8%B1-%D8%A8%D8%B0%D8%B1-%D8%A8%D8%A7%D8%AF%D8%A7%D9%85-%D8%B2%D9%85%DB%8C%D9%86%DB%8C-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/" title="مقدار بادام در هکتار">мақолаи миқдори бодам дар гектар</a> Ин метавонад нуқтаҳои монандро дар бораи ҳисобкунии ҳаҷмии об равшан кунад.</p><p></p><h2>Масъалаҳои амалӣ барои коҳиши хароҷот ва афзоиши самаранокии истеҳсол</h2><p>Кам кардани хароҷоти охирини парвариши бумбаз бо тасмаи чизи дар як гектар танҳо ба харидани моддаҳои асосӣ маҳдуд нест, балки идоракунии ҳангоми парвариш нақши муайянкунанда дорад. Дар ин қисмат дастурамали амалӣ барои деҳқонҳо пешниҳод мешавад.</p><h3>Усулҳои ҳосилбардорӣ ва омода кардани зери бумбаз</h3><ol><li><strong>Омодакунии дақиқи зери бумбаз:</strong> Бумбаз дар хокҳои шағоли-чӯрмики ва бо решаҳои чуқур аз сабаби ниёз ба решаҳои қавӣ беҳтар меафшояд. истифодаи рафҳои дақиқ пеш аз боркунӣ таъмин мекунад, ки тасмаи чизӣ дар чуқурии мувофиқ (одатан 10 то 15 сантиметр) ҷойгир шавад.</li><li><strong>Зичии ҳосилбардории мувофиқ:</strong> Зичии ҳосилбардории бумбаз хеле ҳисос аст. Зичии зиёд боиси афзайиши зиёди шохкулонӣ ва коҳиши самаранокӣ мегардад. Зичии кам низ боиси талафоти замин мешавад. Ҳисоб кардани фосилаи қаторҳо ва гиёҳҳо вобаста ба намуди тоҷ (якядро ё дуюдро) зарур аст. Масалан, агар фосилаи қаторҳо 65 сантиметр бошад, бояд таъмин карда шавад, ки тасмаи чизӣ дақиқан дар миёни ду қатор ё дар канори қаторҳои асосӣ (вобаста ба намуди тасмаи дугона ё ягона) ҷойгир шавад.</li><li><strong>Истифодаи навори дрип дутоба:</strong> Барои баклажан, наворҳои дрип дутоба (Double-sided drip tape) тавсия дода мешаванд, зеро таъмини баробари об ба решаҳо аз ду тараф, системаи решаиашонро мустаҳкам карда, зериши об дар хӯрокҳо-и парҳезӣро кам мекунад.</li></ol><p></p><h3>Идоракунии абйор ва ғизои асосноккунии шланг</h3><p>Ӯзкунӣ бо навори дрип (Fertigation), гарчанде ки маолифи таҷҳизотро каме зиёд мекунад, вале маолифи харидани абйор ва маолифи дасти-зӮр ба паҳкунии абйорро бештар кам мекунад. Шумо метавонед абйорҳое, ки ҳал мешаванд, тавассути наворҳо бевосита ба хок барсозед. Ин усул боиси он мегардад, ки абйор маҳз дар минтақаи решаҳо (Rhizosphere) ҷамъ шуда бошад. Барои беҳтар кардани ин раванд, беҳтар аст, ки дар асоси таҳлили хокатон, барномаи ғизои шахсӣ дошта бошед. Илова бар ин, диққат диҳед, ки консентратсияи абйорҳое, ки барои баклажан истифода мешаванд, бояд зиёда аз сарҳади иҷозатшуда набошад, зеро шорбобшавии хоки дар атрофи навори дрип метавонад ба решаҳо зарар расонад ва сармашавии ивазкунии мекашад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/هزینه-کشت-بامیه-با-نوار-تیپ-در-هکتار-کاربرد-عملی.webp" alt="هزینه کشت بامیه با نوار تیپ در هکتار - تصویر 2"/><figcaption>Масхрати ҳосил дар як гектар навори дрип баклажан</figcaption></figure><h3>Беҳтаркунии система ва ҳалли нуқсонҳо</h3><p>Яке аз бузургтарин хароҷотҳои пинҳонӣ дар навори дрип баста шудани тамғаҳои (чунке) мебошад. Истифодаи филтрҳои мувофиқ (сифат ё тӯрӣ) ва назовшавии мунтазами система, умри фоиданоки наворро зиёд мекунад. Агар баклажанро дар канори маҳсулот дигар парҳиз кунед, шумо метавонед аз <a href="https://navar-abyari.ir/red-bean-seed-per-hectare-irrigation-tips/" title="نکات آبیاری لوبیا قرمز">Нуктаҳои оборӣи бӯнои сурх</a> Илҳом гиред, зеро ҳарду ниҳод дар оилҳои гуногун будан, наботот чунин дар марҳилаҳои ҳассоси рушд ниёзҳои монанди обёрӣ доранд ва идоракунии филтрҳо дар онҳо хеле наздик аст.</p><h2>Таҳлили молиявӣ ва баромади сармоягузорӣ</h2><p>Барои оё донед <strong>эҳтиёҷоти кӯрпаки барҳуби (барҳиб) бо тасмари капель дар як гектар</strong> барои шумо тобеъ аст ё не, бояд як модели соддаи молиявӣ созед. Фарз кунед, ки эҳтиёҷоти харидани тасмари капель, лампҳо ва насб дар як гектар X томон аст. Омоидагии муфоди тасмари капель одатан 2 то 3 мавсум аст (вобаста ба сифат ва шароити амалиётӣ). Пас, эҳтиёҷоти солаи тасмарро ба 2 ё 3 тақсим кунед. Аз тарафи дигар, ҳисоб кунед, ки бо зиёдшавии ҳосилнокии барҳиб (масалан, аз 1500 килограмм дар системаи анъанавӣ ба 2500 килограмм дар системаи қатрагонӣ) ва кам шудани эҳтиёҷоти об ва қувваи корӣ, фоидаи холисои шумо дар ҳар гектар чӣ қадар зиёд мешавад. Агар фарқияти умумии фоидаи холисо бо эҳтиёҷоти иловагии тасмари капель дар давраи умри он мусбат бошад, системаи тасмари капель аз рӯи иқтисод асоснок мешавад. Дар аксари минтақаҳои Эрон бо камбудии шадиди об, ин муодила ба нӯфуди системаҳои фишори дорост.</p><table border="1" cellpadding="5" cellspacing="0" style="width:100%; border-collapse: collapse;"><thead><tr><th>Ҷои ҳисобкунии эҳтиёҷот</th><th>Анъанавӣ (обёрӣ сатҳӣ)</th><th>Тасмари капель (дақиқ)</th><th>Шарҳи муфассал</th></tr></thead><tbody><tr><td>Арзиши об</td><td>Баланд (тақрибан 40%)</td><td>Паст (тақрибан 15%)</td><td>Бартарии намии системаи оварии тамаддунӣ то 95% аст</td></tr><tr><td>Арзиши коркунии инсонӣ</td><td>Хеле баланд (обёрӣ, зарардигарӣ)</td><td>Кам (гиноиш бо маҳлул)</td><td>Автоматизатсияи анборҳо меҳнатро кам мекунад</td></tr><tr><td>Мевагӣ (тонна дар гектар)</td><td>Миёна</td><td>Хеле баланд</td><td>Рисидани беҳтар ва кӯдакӣ бадтар</td></tr><tr><td>Сафоди тоза дар ҳар гектар</td><td>Кам</td><td>Бештар</td><td>Нуқтаи охирии сармоягузории нварчаҳои чанг</td></tr></tbody></table><h2>Саволҳои маъмул (FAQ)</h2><p>Дар поён ба саволҳои бисёр такроршуда дар бораи <em>хароҷоти парҳезии бамиё бо нварчаҳои чанг дар як гектар</em> ҷавоб медиҳем.</p><h3>1. Фарқи хароҷоти нварчаҳои чанг бо системаи босқинаи собит чӣ қадар аст?</h3><p>Нварчаҳои чанг хароҷотро ба таври назаррас камтар нисбат ба босқинаҳои собит (Drip emitters) доранд, зеро як бор истифодашаванда буда, насбшавии онҳо тезтар аст. Босқинаи собит хароҷоти ибтидоии бештар дорад, вале умри фоидаовардояндаш 5 то 7 сол аст. Барои бамиё, ки одатан як бор дар сол парҳез мешавад, нварчаҳои чанг аз ҷиҳати иқтисодӣ мувофиқтар аст, магар ин ки шумо парҳезаи ду барориш дошта бошед.</p><h3>2. Оё истифодаи нварчаҳои чанг хароҷоти тоҳиро зиёд мекунад?</h3><p>Не, харҷи фармонгӣ аз системаи оҳобарӣ вобаста нест. Аммо бо диққати бештар дар ғавронӣ ва табақаҳои якхела, хӯрандани фармонгӣ кӯтоҳтар ва дар ҳар гектар фармонги камтар (бо сабаби хориҷоти камтар) лозим мешавад, ки ин умуман метавонад ба тавозун дар харҷи фармонгӣ оварда расонад. Барои муқоисаи харҷи фармонгӣ дар ҳар гектари маҳсулотҳои дигар, ба <a href="https://navar-abyari.ir/corn-seed-rate-per-hectare/" title="نرخ بذر ذرت در هکتار">суръати фармонги задукориро дар ҳар гектар</a> дида баред, албатта, ин рақамҳо барои задукорӣ аст ва хӯрандани фармонгӣ суръати гуногун дорад, аммо усули ҳисоб якхела аст.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/هزینه-کشت-بامیه-با-نوار-تیپ-در-هکتار-جزئیات-فنی.webp" alt="هزینه کشت بامیه با نوار تیپ در هکتار - تصویر 3"/><figcaption>crop cost per hectare drip tape хӯрандани фармонгӣ</figcaption></figure><h3>3. Чӣ тавр аз пӯшидан нуби тап дар ҳини корзани хӯрандани фармонгӣ пешгирӣ кунем?</h3><p>Истифодаи филтри мувофиқ (бештар аз ҳама санҷишгори 100-120 меш), танзими фишори об дар ҳудуди тавсияшуда (одатан 1 то 2 бар барои нубҳои монанда), ва шустани ибтидоии система пеш аз ҳар фисли корзанӣ, калиди асосӣ аст. Инчунин, истифодаи калсий гипохлорит ё оби кимиёвӣ ба миқдори кам метавонад аз рушди хумунҳо дар нуб пешгирӣ кунад.</p><h2>Хулоса ва тавсияи охирин</h2><p>Таҳлили харҷи корзани хӯрандани фармонгӣ бо нуби тап дар ҳар гектар нишон медиҳад, ки гарчанде сармояи ибтидоӣ барои харидани системаи оҳобарӣ вуҷуд дорад, аммо ҷамъоварии тавозунҳо дар об, энергия, нерӯи меҳнат ва афзоиши ҳосил, ин харҷҳоро зуд ҷуброн мекунад. Барои муваффақӣ, деҳқонон бояд аз ҳисоби дақиқ масофагирии нуб ва партовкунии (Emitter spacing) ғафил набошанд. Мудиряти дурусти намакӣ дар хокҳои намакдор низ тавассути оҳобарии тамғавуқ ва истифодаи нуби тап беҳтар идора мешавад, зеро намакӣ дар атрофи решаҳо камтар мешавад.</p><p></p><p>Дар ҳолати ниҳоӣ, пеш аз хариди система, тавсия дода мешавад, ки ба асоси намуди хок ва иқлими минтақаи худ бо мутахассиси овардан машварат кунед, то андозаҳои системаи овардишавӣ, фишори корӣ ва қуввати помпоро имтиёзнок кунед. Бо гурӯҳбандии дониши техникӣ ва таҳлили иқтисодӣ, метавонед ки корт ба надукии содиршавӣ ва устувор табдил диҳед. Шиносоӣ бо <a href="https://navar-abyari.ir/%D9%85%DB%8C%D8%B2%D8%A7%D9%86-%D8%A8%D8%B1%D8%AF%D8%A7%D8%B4%D8%AA-%D8%AC%D8%B9%D9%81%D8%B1%DB%8C-%D8%AF%D8%B1-%D9%87%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/" title="میزان برداشت جو بهاره در هکتار">Миқдори ҳосили палвонаки баҳорӣ дар гектар</a> ва дигар маҳсулот ба нақшакашии сикли кӯпои ояндагӣ низ мекомад.</p>','Арзиши кишт нахӯд бо навори ТИП дар ҳектар: Раҳнамои иқтисодӣ','Таҳлили пурраи ҳароҷоти парвариши памидӯр бо усули нозаркӣ барои ҳектар, аз ҷумла сармояҳои доимӣ ва тағйирёбанда, ҳисобкунии оби масраҳшуда ва роҳҳои коҳиши ҳароҷотҳо барои деҳқонон. Агар шумо ҷустуҷӯи самаранокӣ зиёдро бошед, ин мақоларо аз даст надиҳед.','publish','closed','closed','arzishi-kisht-nakhud-bo-navari-tip-dar-hektar',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
