INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<p>Интихоб <strong>Фосилаи нӯри риббон дар парвариши маш</strong> Яке аз мушкилоти муҳим барои деҳқонон ва мутахассисони об буда, бевосита ба самаранокии обёрӣ ва сифати маҳсул таъсир мерасонад. Маш дар ҳолие ки як растании даноӣ бо решаҳои заиф ва ҳассосияти баланд барои фурӯ рехтани дандонҳо мебошад, ба идоракунии ҳошёни системаҳои обёрии нӯрӣ ниёз дорад. Дар ин дастёр, мо аз назарияи фосилаҳо то амалиёти майдонӣ, тамоми паҳлуҳои техникӣи ин мавзӯъро баррасӣ мекунем, то ки шумо бо бовури комил, ҷойгиркунии нӯрҳои риббон худро танзим кунед.</p><h2>Муқаддима дар бораи аҳамияти ҷойгиркунии нӯри риббон дар маш</h2><p>Системаҳои нӯри риббон (Drip Tape) ба сабаби он ки арзонтар аз системаҳои доимии нӯрӣ будаанд ва имконияти ҷамъоварӣ ва баъд аз тамом шудани фасли парвариш ба истеъмол баръгардонидан доранд, машҳур шудаанд. Аммо ин система ба дақиқии баланд дар фосилаи нӯрҳо аз маркази саф ва фосила байни нӯрҳои ҳамсоя ниёз дорад. Мақсади асосӣ, эҷоди минтақаи тар (Wetted Front) якдил аст, ки решаҳои машро дар бар мегирад. Агар фосилаи нӯрҳо аз ҳам зиёд бошад, шикофҳои хушк барои фишори об дар давраи пур шудани дандонҳо сабаб мешаванд. Агар фосилаҳо хеле наздик бошанд, хароҷоти об дар минтақаҳои ғайр аз решаҳо рух медиҳад ва ба афзоиши сарфнокии система оварда мерасонад.</p><h2>Маъёрҳои техникӣи фосилаи нӯри риббон дар парвариши маш</h2><p>Муайян кардани фосилаи дақиқи нӯри риббон ба тағйирёбанدهҳо чун қирраи хок, чуқурии фурӯ рехтани дандони маш ва шиддати офтоб вобаста аст. Бо вуҷуди ин, маъёрҳои умумӣ барои минтақаҳои мулоим ва ним хушки Тоҷикик чунин аст:</p><ul><li><strong>Фосилаи нӯри риббон аз маркази саф (Center-to-Tape Distance):</strong> Оддани 5 то 10 сантметр тавсия карда мешавад. Масофаи 10 сантметр барои кам кардани буғ ва пешгирӣ аз бемориҳои кордашудаи пӯсмон ҳангоми намии баланди қабатҳои зерин мувофиқ аст. Масофаҳои аз 5 сантметр камтар метавонанд боиси фалак шудани решаҳои реша дар хокҳои шаштӣ ва мавафиг шудани растаниҳо гарданд.</li><li><strong>Танзими як навбати аз ду навбат:</strong> Барои ҳазорҳои сабзи 60 то 70 сантметр, истифодаи як навбати шубора дар марказ ё ду навбати тарафбошанда бо масофаи 10-15 сантметр аз маркази ҳазор маъмултар аст. Дар системаи дунавбат, масофа байни ду навбат бояд чунин бошад, ки минтақаи намдорини ҳарду навбат тақрибан ба якдигар мерасанд.</li></ul><table><tbody><tr><th>Навъи хок</th><th>Тавсияи масофаи навбат аз марказ</th><th>Тавзеҳот</th></tr><tr><td>Хокҳои рӯйзиста ва сабук</td><td>15-20 сантметр</td><td>Хуки рагунокӣ ба намуди ҳаҷми бештари решаҳо ниёз дорад; риширо дуртар аз марказ ҷойгир кунед.</td></tr><tr><td>Хуку силовӣ ва миёна</td><td>8-12 сантиметр</td><td>Ҳолати мувозинатноктарин; стандарти саноатӣ дар аксари заминҳои Ирон.</td></tr><tr><td>Хукҳои гилӣ ва вазнин</td><td>4-6 сантиметр</td><td>Барои пешгирии ҷамъшавии об ва фритишани решаҳо, масофаро наздик ба сабзи ҷойгир кунед.</td></tr></tbody></table><p>Барои фаҳмиши беҳтар ошёршавии об дар хок, омӯзиш дар бораи <a href="https://navar-abyari.ir/%D9%85%DB%8C%D8%B2%D8%A7%D9%86-%D8%A8%D8%B1%D8%AF%D8%A7%D8%B4%D8%AA-%D8%AC%D9%88-%D8%AF%D9%88%D8%B3%D8%B1-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/">Ҳаҷми ҳосилдиҳии гунаву дуҳи дар як гектар</a> Мумкин аст, ки шабоҳатҳо ва фарқиятҳоро дар оройдодани партов ва донии ошкор созӣ. Ҳамин тавр, ки мош наботи донӣ аст, аммо рафтори решааш бо сабзиҳо ва дигар набототи донӣ шабоҳатҳо дорад, ки дар пайваст боло таҳлил шудааст.</p><h3>Нуқтаҳои амалии насб ва нигоҳдории</h3><p>Иҷрои дурустии масофагирии на бояд танҳо дар кағоз бошад. Дар марҳилаи амал, истифодаи ширҳанҳои дақиқ ё риштаҳои роҳнам кӯмак мекунад, ки дар дарозии сатр, инҳирофи ришта аз марказ таҳти назорат бошад. Баъд аз кортиш, пеш аз оғози аввалин ободӣ, яқин шавед, ки риштаи туп бе пукхурдагонӣ (Kink) дар хок паст аст. Пукхурдагонӣ ба тағйири суръати ҷараён ва эҷоди нуқтаҳои заифии ришта дар муддати дароз оварда мерасонад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-ماش-استانداردهای-توصیهشده-تصویر-شاخص.webp" alt="فاصله نوار تیپ در کشت ماش: استانداردهای توصیه‌شده - تصویر 1"/><figcaption>drip tape spacing row layout crop маш</figcaption></figure><p>Лазим аст эҳтиёт шавед, ки масофагирии риштаи туп дар ғалғи мумкин аст каме гуногун бошад, зеро ғалғӣ аз ҷиҳати сохтори решаҳо ва ниёз ба об, бо маш фарқиятҳои хурди дорад. Ҳамин тавр, принсипҳои умумии идоракунии масофаи риштаҳои тупӣ дар сабзиҳои партоӣ умумӣ аст ва метавонад барои кортишҳои дигар роҳнамоии хуб бошад.</p><h2>Идоракунии фишор ва тарроҳии хатҳои артериявӣ</h2><p>Ҳамоҳангӣ бо тарҳи дурустии шабакаи артериявӣ (Manifold) баста шудааст. Агар хатҳои артериявӣ параллел бошанд ва дар фишори якхела ҷараён дошта бошанд, тақсимоти об дар дарозии ришта якхела хоҳад буд. Дигарин ҳолат, қисми охири ришта хушк ва қисми аввали он тар хоҳад буд, ки боиси ғайрисимметрикии рушди маш дар сатр мешавад.</p><ol><li><strong>Ҳисоби паст рафтан шидати ҳидрофикӣ:</strong> Бо зиёд шудани тӯлои зироатхона, шидат дар поёни ҳатари асосӣ паст меояд. Барои ҷӯбакунии ин, бояд қутри лулаи асосӣ (Mainline)-ро зиёд кунед ё тӯлои хатҳои мувозиро кӯтоҳтар тарҳрезӣ намоед.</li><li><strong>Талақуми ришта:</strong> Риштаҳои нави дорои сӯрохиҳо бо ҷараёни 1/27 литр дар соат мебошанд. Ин суръат барои пахта дар марҳалаи афзоиш мувофиқ аст, аммо дар марҳалаи пур шудани чӯлобҳо, эҳтимолан ба зиёд кардани ҳаҷми об ниёз доред. Дар ин сурат, масофаи байни риштаҳоро тағйир надиҳед, балки давоми оромоишро танзим кунед.</li></ol><p>Барои ошноӣ бо тафсилоти техникӣ риштаҳо ва намуди риштаҳои мувофиқ барои наъматҳои ҳисобкунандавӣ, метавонед ба <a href="https://navar-abyari.ir/nuqtahoi-muhim-hangomi-istifodai-lundahoi-tipisi-baroi-obyori/">Нуқтаҳои муҳим ҳангоми истифодаи лӯлаҳои ришта барои оромоиш</a> масъалат кунед. Ин дастаказӣ ба хусусиятҳои полимерии ришта ва моқовиматашон нисбат ба ниони UV низ дахл дорад.</p><h2>Тасири масофаи ришта ба сифат ва миқдори маҳсулот</h2><p>Тадқиқотҳо нишон медиҳанд, ки optimize кардан <strong>масофаи равонҳои тиб дар наъмури ғурус</strong> метавонад то 15 фоиз дар истеъмoli об ихтиёр кунад, дар ҳоле ки самаранокии ҳар гектарро устувор нигоҳ медорад ё ҳатто меафзояд. Вақте ки масофаи равони оптималӣ бошад, решаҳо қисмати намноки рӯи равонро пурра пӯшидан мекунанд ва ниёз ба ҷустуҷӯи об дар ҳодҳои хушк надоранд. Ин энергияи растаро барои гулдан ва пур шудани дона ҷудо мекунад, на барои сохтани решаҳои хурд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-ماش-استانداردهای-توصیهشده-کاربرد-عملی.webp" alt="فاصله نوار تیپ در کشت ماش: استانداردهای توصیه‌شده - تصویر 2"/><figcaption>drip tape spacing row layout crop маш</figcaption></figure><p>Илова бар ин, интихоби масофаи муносиб имкон медиҳад, ки аз гузарониши дақиқии нӯришкунандагӣ (Fertigation) истифода баред. Агар равонҳо аз ҳамдигар хеле дур бошанд, нӯришкунандаҳои нитрогенӣ ба сабаби дараҷаи баланди гузаштан дур шуда мераванд. Агар хеле наздик бошанд, ҷамъ шудани моддаҳои нӯришкунанда дар як нуқта ба сӯзидани решаҳои ғурус оварда мерасонад. Мувозинати масофаи равонҳои тиб роҳро барои нӯришкунандагии бехатар ва муассир мекушояд.</p><p>Дар деҳқонӣҳое, ки ҷамъшавии наъмуриро иҷро мекунанд, ё агар шумо равонҳои тибро барои ғирмондани сабзавоти дигар чун салат ё хурма истифода баред, ошноӣ бо масофаҳои дигар ба шумо кӯмак мекунад, ки қоидаҳои умумиро фаҳмед. Масалан, тадқиқот <a href="https://navar-abyari.ir/lula-3-dyimmagi-kharid-istifoda-imkoniyathoi/">имконияти харидан ва истифодаи лӯлаи тиб 3 миллиметрӣ</a> нишон медиҳад, ки истифодаи равонҳои ғафсттар (масалан, 4 ё 5 миллиметр) дар қаторҳои дунавӣ метавонад умри кории равонро зиёд кунад ва қарзи аз паредани равонро ба ҳадди ақал расонад.</p><h2>Ҷавоб ба саволҳои маъмул (FAQ)</h2><h3>1. Оё имкони тағйир доидам масофаи нӯра баъд аз кишоварӣ вуҷуд дорад?</h3><p>Не, тағйир додани масофаи нӯра аз маркази қаторӣ баъд аз кишоварӣ амалан ғайриимкон аст, зеро нӯра бояд дақиқан зери соядиҳанда ва дар ҳудуди решаҳо ҷой гирад. Бинобар ин, ин қарор бояд пеш аз партофтани дунбҳо дар нақшаи кишоварӣ муайян ва тасмим шавад.</p><h3>2. Масофаи стандартӣ дар хокҳои рехин чӣ гуна аст?</h3><p>Сабаби қабулкунандагии баланди хоки рехин, нӯраҳо бояд аз маркази қаторӣ дуртар (тақрибан 15-20 сантиметр) ҷойгиранд, то ҳаҷми тар (намдор) васеътар бошад ва об ба зудӣ аз даст наравад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-ماش-استانداردهای-توصیهشده-جزئیات-فنی.webp" alt="فاصله نوار تیپ در کشت ماش: استانداردهای توصیه‌شده - تصویر 3"/><figcaption>масофаи нӯраи қатара, ҷобаҷогузории қаторӣ, фармаи маш</figcaption></figure><h3>3. Нақши шӯрии об дар масофаи нӯраи тейп чӣ гуна аст?</h3><p>Дар обҳои شور, муҳандисон одатан тавсия мекунанд, ки аз нӯраҳо бо суръати орамони баландтар ва масофаҳои физикӣ якхела истифода баред, аммо ҳаҷми бештари барои шустан (Leaching) дар охир илова шавад. Масофаи физикии нӯра аз сағол дар ин ҳолатҳо тағйироти муҳим намедиҳад, аммо рақори система танзим мешавад.</p><h2>Хулоса ва тавсияҳои ниҳоӣ</h2><p>Оҳангсозӣ <strong>Масофаи нӯри тип дар кунҳи машу</strong> Як раванди муътабар бар маълумот такяъ мекунад. Шумо бояд хуракшиносиро, навъи навъҳои машу ва шартҳои об ва ҳавои минтақаро бо ҳам комбинат кунед. Оғоз аз миёнаҳои стандартӣ (тақрибан 10 сентиметр дар хуракҳои миёна) ва баъдан тавассути ченкунии амалӣ намуди хуракӣ (бо дастгирӣ ченкуни об ё усули пимпинг) масофаро ислоҳ кардан, роҳи бемаҳолтарин барои муваффақият аст.</p><p>Ё инчунин диққат ба нигоҳдории ва зиёд кардани умри системаи ҳайатӣ аст. Барои шиносӣ бо усулҳои пешгирии маҳшавии сӯрохҳо ва зиёд кардани истифодаи системаҳои чисткунии қатрагӣ, метавонед мақолаи <a href="https://navar-abyari.ir/afzaliyathoi-lentai-qatragi/">Зиёд кардани истифода аз нӯри обёрӣ чисткуни қатрагӣ</a> ро хондан. Ин нуқтаҳо ба шумо кумак мекунанд, ки сармоягузории худро дар системаи обёрӣ барои солҳои оянда нигоҳ доред ва аз хароҷоти ивазкунии муқаддами нӯри пешгирӣ кунед.</p><p>Дар ниҳоят, як системаи нӯри тип созшуда, самаранокии иқтисодии кунҳи машуро бо кам кардани хароҷоти об, энергия ва қувваи корӣ баланд мебарорад ва байни ҳуқуқи маҳаллӣ барои кунҳҳои минбаъда нигоҳ медорад. Шумо инчунин метавонед бо хондани таҷрибаҳои муваффақтар деҳқонон дар истифодаи лӯлаҳои нӯришуда барои мӯрдаҳои калон <a href="https://navar-abyari.ir/%d8%b4%d8%b1%d9%8a%d8%b7-%d8%a7%d9%84%d8%b1%d9%8a-%d8%a8%d8%a7%d9%84%d8%aa%d9%86%d9%82%d9%8a%d8%b7-%d9%81%d9%8a-%d8%aa%da%a9%d8%b1%db%8c%d8%aa/">Тасмаи нӯрдаккунии чормағзӣ дар ибтидо ва ҳалҳои пешрафта</a> фароҳам оред, гарчанде ки ин манбаъ омехтаи форсӣ/арабӣ аст, вале принсипҳои системаи тасмаи тип дар он қатъан барои моҳиҳои Ирон иҷрошаванда аст.</p>','Фавъаи навори тип дар карибкории мош: Стандардҳои тавсияшуда','Дар ин мақола мо масофаи дақиқи ҷиноқи чӯб, стандартҳои тавсияшуда, вобаста ба намуди хок ва системаи обёрӣ ва нуқтаҳои муҳими иҷроиш, барои кори беҳтари лӯлаҳои чӯбро баррасӣ мекунем.','publish','closed','closed','fawwaai-nawari-tip-dar-karibkorii-mosh-standardii-tavsiyashuda',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
