INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<p>Деҳқонон ҳамеша дар ёфтани роҳҳои беҳтар кардани хароҷот ва зиёд кардани ҳосил дарозӣ ҳастанд. Яке аз саволҳои маъмул,  <strong>миқдори тухми сирбир бар ҳектар</strong> мебошад. Муайян кардани дурусти ин миқдор, на танҳо як рақами хушк, балки калиди асосӣ барои идоракунии захираҳо, кам кардани истеҳсоли энергия ҳангоми нишаст ва дар охир зиёд кардани фурӯши маҳсулоти кораст. Дар ин дастур, мо раванди ҳисобкуниро аз сифр то сад шарҳ медиҳем, то ки шумо бо эътимод таъмин гиред ва то метавонед тухмро харид ва нишонед.</p><h2>Чаро ҳисобкунии дақиқи миқдори тухми сирбир бар ҳектар муҳим аст?</h2><p>Тухми сирбир бо сабаби хусусиятҳои мушаххас, ба монанди ниёз ба нишасдонии чуқур ва пайдо нашудани зудии решаҳо, ба нақшагирии дақиқ ниёз дорад. Агар шумо аз дастурҳои мисли ҳисобҳои нишасдонӣ истифода барда бошед, эҳсос карда бошед, ки zichiiги ниҳоии андорӣ бевосита бо ҳаҷми тухми истифодашуда вобаста аст. Барои сирбир, ин zichiiг бояд чунин бошад, ки имконияти рушди пурраи сирбирҳоро фароҳам орад, бе он ки рақобати шадид байни решаҳо ба хурдшавии маҳсулот оварда расонад.</p><h3>Омилҳои таъсиррасон ба муайян кардани zichiiги тухм</h3><ul><li><strong>Навъи нависарҳо:</strong> Нависарҳои сирбери калон ба фазои бештар ниёз доранд.</li><li><strong>Сифати тоҷӣкӣ:</strong> Дараҷаи набурдонидани тоҷи тоза вобаста ба истеҳолкони тоҷӣ фарқ мекунад.</li><li><strong>Усули боридан:</strong> Омозиҳои муосири боридан нисбат ба боридани дастӣ дақиқати баландтар доранд.</li><li><strong>Ҳавои минтақа:</strong> Дар минтақаҳои хушк, идоракунии оборӣ нақши муҳимро дар интихоби фосилаҳо боз мекунад, ки шумо бо таҳқиқоти ихтисосӣ оид ба обории чукандора ҷиҳатҳои монандро таҳқиқ карда метавонед.</li></ul><><h2>Формулаҳои ҳисоб кардани миқдори тоҷи пуршакр барои ҳектар</h2><p>Барои ҳисоби дақиқ, ба ду тағйирёбандаи асосӣ зарурат доред: фосилаи сатҳҳо (метр) ва фосилаи чӯби тоҷ (сантиметр). Фарзиянд, ки фосилаи сатҳҳо 15 сантиметр ва фосилаи чӯби тоҷ 5 сантиметр бошад. Ин маънои онро дорад, ки дар як метри дарозии сатҳ тақрибан 20 чӯби ғиёби боридан мавҷуд аст.</p><ol><li>Ҳисоби шумораи сафҳҳо дар як гектар: Як гектар маънояш 10,000 метри мурабат аст. Агар андозаи байни сафҳҳо 15 сантиметр (0.15 метр) бошад, шумораи сафҳҳо баробар аст ба тақсимшавии 10,000 ба 0.15, ки тақрибан 66,666 сафҳ ҳисоб карда мешавад (бо фарзияи барории замина). Аммо усули содатар ин аст: масоҳати як сафҳи якметрадро ба назар гиред. Андозаи умумии сафҳҳо ба қири замина тақсим карда мешавад.</li><li>Ҳисоби шумораи сарҳои сармо дар ҳар метри дарозӣ: Масофаи сарҳо 5 сантиметр аст, бинобар ин дар як метр 20 сарҷойгир мешавад.</li><li>Ҳисоби шумораи умумии сарҳо: Шумораи сафҳҳои дарозӣ × 20 сар дар метр × дарозии замина. Як формулаи содатар барои тахмини назариявӣ ин аст: (10,000,000 / андозаи сафҳ) × (100 / андозаи сар). Агар андозаи сафҳ 0.15 м ва андозаи сар 0.05 м бошад: (10,000,000 / 0.15) × (1 / 0.05) ҳисоб намешавад, балки чунин аст: Шумораи сафҳҳо дар қири замина (бо фарзияи дарозии 100 метр барои ҳар сафҳ дар як блок 10 Ҳазор метри мурабатиаш). Беҳтарин усул: ҳисоби масоҳати ҳар сар. Масоҳати ҷудошуда барои ҳар сар = 15 сантиметр × 5 сантиметр = 75 сантиметри мурабат. Барои як гектар (10,000,000 сантиметри мурабат), шумораи сарҳо баробар аст ба тақсимшавии 10,000,000 ба 75, ки 133,333 сар мешавад. Бинобар ин, ба шумо 133,333 сар лозим аст.</li></ol><p>Ҳоло барои табдили шумораи сарҳо ба вазни тоб, ба андозаи сар ниёз доред. Як сари миёнаи сармо тақрибан 3 то 4 грамм вазн дорад. Агар миёнаро 3.5 грамм ҳисоб кунем, вазни умумии тоб баробар аст ба 133,333 × 3.5 грамм = 466,665 грамм ё тақрибан <strong>466 килограмм</strong>. Ин рақами идеалӣ аст. Дар амал, ҳамеша 5 то 10 фоиз илова кунед, то аз гум шудан ё хунук шудани тобҳо бо сабаби нобаробарии замина пешгирӣ карда шавад. Пас миқдори тоби сармо дар гектар метавонад аз <strong>470 то 520 килограмм</strong> тағйир ёбад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-سیر-در-هکتار-راهنمای-جامع-تصویر-شاخص.webp" alt="مقدار بذر سیر در هکتار: راهنمای جامع - تصویر 1"/><figcaption>Norma poshi bo hektar meҳvarot sib</figcaption></figure><h3>Ta\'siri obiyoriyi tomchaxoz bar fazaik poshi</h3><p>Istifoda from <a href="https://navar-abyari.ir/%d9%86%d8%ad%d9%88%d9%87-%d8%a7%d9%86%d8%aa%d8%ae%d8%a7%d8%a8-%d9%86%d9%88%d8%a7%d8%b1-%d8%a2%d8%a8%db%8c%d8%a7%d8%b1%db%8c-%d9%82%d8%b7%d8%b1%d9%87-%d8%a7%db%8c-%d9%85%d9%86%d8%a7%d8%b3%d8%a8/" title="نحوه انتخاب نوار آبیاری قطره ای مناسب">Naviha yoki riboni obiyoriy tomchaxoz</a> Ba shumo imkon медиҳад, ки фаволидҳи ларзҳо-ро каме камтар дар назар гиред, зеро rеgеhҳо дарёфти беҳтар ба obи меҳварот ёбанд. Аммо нуқтаи асосӣ ин аст, ки навии type бояд дақиқан дар миёни ду ларз ҷойгир шавад, то рақобати rеgеhҳо дар баробари ob кам гардад. Барои фаҳмиши беҳтари механикаи интиқоли ob, бозниҳон ба мақолаи <a href="https://navar-abyari.ir/%D9%85%D9%82%D8%AF%D8%A7%D8%B1-%D8%A8%D8%B0%D8%B1-%D8%B4%D9%86%D8%A8%D9%84%DB%8C%D9%84%D9%87-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/" title="مقدار بذر شنبلیله در هکتار">Роҳнамои ҳисоб кардани нормаи poshi барои кўкоро</a> инчунин бозниҳон кунед, зеро принсипи зичии poshi дар он низ монанд аст.</p><><h2>Малумотҳои амалӣ барои хариду омода кардани poshi</h2><p>Ҳангоми харидани сасиҳои тухм, ба саломатӣ ва сафт будани онҳо диққат диҳед. Сасиҳои нарм ё кӯбидашуда бояд намезинанд. Барои афзун кардани дақиқии ғармозанӣ, метавонед аз машинаҳои ғармозани тухм истифода баред, ки фосилаҳоро устувор нигоҳ медоранд. Агар аз усули дастӣ истифода баред, кашидани як чӯб барои паҳлукунӣ кӯмак мекунад, ки фосилаи 15-сантиметрӣ риоя шавад.</p><h3>Идоракунии об ва тарроҳӣ</h3><ul><li>Тухми сибу тобшӣ ба тарии баланди замин ниёз дорад, аммо тағйироти нохуди тарӣ метавонад боис ба шикастани саси гардад. Истифодаи системаҳои обёркунии дақиқ муҳити решаҳои растаниро устувор менамояд.</li><li>Пӯшиши замин бо плёнка (малч) метавонад афзоиши ҳашаротро кам намуда, тарро нигоҳ дорад. Ин кор ниёз ба обёркунии такрорӣ-такрориро кам мекунад.</li><li>Барои шиносоӣ бо самтҳои системаҳои нав, ба <a href="https://navar-abyari.ir/foidai-norabiyari-tip/" title="فواید نوار آبیاری تیپ">фоидаҳои обёркунии нӯҳураи тӯп</a> муроҷиа кунед, ки нишон медиҳад, чӣ гуна ин технология метавонад барои маҳсулоти хурд, ба монанди сибу тобшӣ, боварӣовар бошад.</li></ul><h2>Сатҳҳои гуногуни зичкӣ ва самтҳо</h2><p>Баъзе деҳқонон қуворои махсуси сармиро зичкории баландтар кӯр мекунанд. Ҷадвали зерин муқоисаи зуд аз зичкориҳо гуногунро нишон медиҳад:</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-سیر-در-هکتار-راهنمای-جامع-کاربرد-عملی.webp" alt="مقدار بذر سیر در هکتار: راهنمای جامع - تصویر 2"/><figcaption>норми ҷарф барои 1 гектар ҳосил сармо</figcaption></figure><table><thead><tr><th>Фавосилаи қаторҳо (метр)</th><th>Фавосилаи ҷойҳо (метр)</th><th>Шумораи қуворо дар 1 гектар</th><th>Озмони тахминӣ баҳорӣ (килограмм)</th><th>Шарҳ</th></tr></thead><tbody><tr><td>0.15</td><td>0,05</td><td>133,333</td><td>466 - 520</td><td>Стандарт барои кӯлоби миёна</td></tr><tr><td>0,20</td><td>0,05</td><td>100,000</td><td>350 - 400</td><td>барои нависҳо-и бошар (bulb)-и калон мувофиқ аст</td></tr><tr><td>0.15</td><td>0.04</td><td>166,666</td><td>583 - 650</td><td>Зичии баланд, ниёз ба намнокии бештар</td></tr></tbody></table><p>Фаромӯш накунед, ки ин рақамҳо тақрибӣ мебошанд ва вобаста ба бегона (бӯяқ) ва шароити заминатон тағйир меёбанд. Барои пухтарон кардани маълумот дар бораи интихоби системаи обёрӣ, ки бо ин зичиҳо мувофиқат мекунад, шумо метавонед <a href="https://navar-abyari.ir/comprehensive-irrigation-tape-greenhouse-guide-0-to-100/" title="راهنمای جامع نوار آبیاری گلخانه">Равонамои умумии обёрӣ бо навар дар боғхона</a> раҳиҳо таҳқиқ кунед, зеро принсипҳои физикии оқим дар наварҳо якхела аст.</p><><h2>Саволҳои зуд-зуд такроршуда (FAQ)</h2><h3>1. Оё миқдори бобуни ҷӯлоро ба ҳектар доимӣ аст?</h3><p>Не, доимӣ нест. Ин миқдор ба андозаи навлҳо, масофаи кундани ҷӯлоро ва намуди хок вобаста аст. Навлҳои боландоғон ба фазои бештар ниёз доранд, дар ҳоле ки навлҳои хурддоғон зичии баландтар доранд.</p><h3>2. беҳтарин вақти кундани ҷӯлоро куҷост?</h3><p>Одатан, дар охири тирамоҳ (ӯктеб ё октябр) кунда мешавад, то ки болгоҳҳо имконияти кофӣ барои пуршудан ва ғаллоғӣ доранд дар тӯли зимистон ва баҳор.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-سیر-در-هکتار-راهنمای-جامع-جزئیات-فنی.webp" alt="مقدار بذر سیر در هکتار: راهنمای جامع - تصویر 3"/><figcaption>seed rate per hectare crop сир</figcaption></figure><h3>3. Оё имкон дорад, ки обдорӣ дар қатраҳо барои сир истифода шавад?</h3><p>Бале, набудиҳистони қатрагӣ яке аз беҳтарин усулҳо барои сир аст, зеро боиси идоракунии намии решаҳо мегардад ва аз вайроншавии сугӯҳҳо дар оқибати тӯл ҷониб мондан дар об пешгирӣ мекунад. Барои бештар маълумот доштан, <a href="https://navar-abyari.ir/perforated-drip-tape-irrigation/" title="آبیاری نوار سوراخ دار قطره ای">рӯҳнамои набудиҳистони нақарии қатрагӣ-и сӯрохнокро</a> баррасӣ кунед, ки шарҳи техникии хуб дар бораи намудҳои нақариҳоро дорад.</p><h2>Хулоса</h2><p>Ҳисобу кӯшиши дақиқ <strong>Миқдори бобиби сир дар гектар</strong> яке раванди илмӣ аст, ки бо назардошти фосилаҳои кишт ва вазни оморҳо пешгӯӣ карда мешавад. Дар ҳолати стандартӣ, тақрибан 450 то 500 килограмм бобиб барои як гектар тавсия карда мешавад. Барои таъмини муваффақият, мо тавсия мекунем, ки аз системаҳои мувофиқи набудиҳистон истифода баред ва ба сифати бобиби харидашуда диққат диҳед. Бо риояи принсипҳои фосилаи кишт ва идоракунии об, шумо метавонед ҳосили аълои меҳвари сир худро дастовард кунед.</p>','Микдори бодаъи сармоишӣ ба ҳар гектар: Раҳнамои умумӣ барои деҳқонҳо','Дар ин мақола бо формулаҳои ҳисоб кардани миқдори бӯи саримпо дар як гектар, масофаҳои муносиби партовашӣ ва таъсири системҳои обёрӣи қатрагӣ ба рушди кӯрӣ шинос мешавед. Раҳнамои умумӣ ва амалӣ барои деҳқонон.','publish','closed','closed','miqdori-bodai-sarmoii-ba-har-hektar-rahnaumi-umumi-baroe-dehqonho',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
