INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддима: Аҳамияти шитобҳои кабударро дар парвариши шамбалӣ</h2>\n<p>Шамбалӣ (Fenugreek) яке аз набототҳои муҳими дармонӣ ва иқтисодӣ аст, ки барои расидан ба ҳосили омада, ба тақсимоти баробари намдодӣ ниёз дорад. Аз байн ба усулҳои гуногуни обёрӣ, <strong>шитобҳои кабудар</strong> барои фарогирии мушаххаси решагӣ, камтарин бегардонӣ ва истифодаи оптималии об яке аз беҳтарин интихобҳо барои парвариши ин гиёҳ гардидааст. Аммо, бисёр деҳқоён мушкилоти пӯшидан кӯлаҳои берунӣ (Emitters) ва коҳиши самаранокии система доранд. Сабаби асосии ин пастшавии самараноки нодидадоштани марҳилаҳои муҳими парвариши шитобҳои кабудар мебошад.</p>\n<p>Дар поён, мо дастарозгирии пурра барои парвариши дурусти шитобҳои кабудар дар боғзорҳои шамбалӣ пешниҳод мекунем, ки принсипҳои механикӣ, кимиёвӣ ва барномаҳои фаслии солро дар бар мегирад. Мақсади мо ин аст, ки тавассути иҷрои дақиқи ин нуктаҳо, умри кории лампаҳоро зиёд карда, ҳосили бо сифати баландтarto ба даст оред. Барои фаҳмиши беҳтари динамикаи афзоиши гиёҳ ва таъсири мутақобилаи он бо системаи обёрӣ, омӯзиш <a href="https://navar-abyari.ir/%D9%85%D8%B1%D8%A7%D8%AD%D9%84-%D9%86%D8%B5%D8%A8-%D9%86%D9%88%D8%A7%D8%B1-%D8%AA%DB%8C%D9%BE/" target="_blank">марҳилаҳои шитобҳои кабудар</a> аз нуқтаи назари муҳити замин низ метавонад фойдаовар бошад.</p>\n\n\n\n<h2>Печораҳои асосӣ дар насб ва парвариши ибтидоӣ</h2>\n<p>Нигоҳдории система аз лаҳзаи навардани он оғоз меёбад. Аввалин ва муҳимтарин омил дар пешгирӣ аз осеб расонидан ба ғизорубанд (drip tape), идоракунии фишори ҳаво дохили кулак мебошад. Фишори зиёдтар аз ҳадди иҷозатшуда боиси пайдошудани таҷҳазҳои хурд дар баданаи полиэтиленӣ мегардад, ки дар тӯли муддати дароз ба рахш об ва паст шудани фишор дар тамоми система мусоидат мекунад. Инчунин, ғизорубанд бояд комилан бо сафҳои гирифтани ғизи (дони) ҷойгир бошад, то ки об мустақиман ба минтақаи решаҳо расад ва аз шоракунии сатҳи хок пешгирӣ шавад.</p>\n<ul>\n  <li><strong>Назорати фишор:</strong> Матлаб аст, ки ба вориди системаи асосӣ аз регулятори фишор (Pressure Regulator) истифода баред, то ки фишори корӣ дар андозаи 1 то 3 бар нигоҳ дошта шавад.</li>\n  <li><strong>Пешгирӣ аз офтуби мустақими офтоб:</strong> Гарчанде ки полиетилен ба таъсири UV моқимат дорад, вале ҷойгиршавии унсирӣ дар ҳавои гарм боиси сахт шудан ва ҳассосшавии бештари кулак ба зарба мегардад. Пушидани мувакқатӣ дар вақти бекористӣ тавсия дода мешавад.</li>\n  <li><strong>Тафтиши пайваستҳо:</strong> Пайвастҳои металлӣ ва пластикӣ бояд ҳар ҳафта саривасат тафтиш карда шаванд. Таҷҳазҳои хурд дар пайвастҳо сабаби асосии ворид шудани хок ва заҳолишавӣ ба дохили система мебошанд.</li>\n</ul>\n\n<h2>Шуставӣ ва таҳвилкунии система: раванди ҳаёатӣ</h2>\n<p>Яке аз мушкилоти асосӣ дар обори тамғагузорӣ ва назари чурпаи қатӣ, афканидани маводҳои кимиёвӣ ва биологӣ дар сангҳои баромадгор аст. Барои анорӣ, ки одатан аз хокҳои чурпакунда истифода мебарад, хатари таҳсилоти механикӣ (Silt Clogging) хеле баланд аст. Бинобар ин, шустани мунтазами система (Flushing) наметавонад тадбирини ихтиёрӣ бошад.</p>\n<ol>\n  <li><strong>Шустани механикӣ:</strong> Дар оғози ҳар мавсими зироат, системаро бо рафтори қавии об ба муддати 10 то 15 дақиқа шӯед, то зарраҳои рег ва санг аз лӯлаҳо берун шаванд.</li>\n  <li><strong>Холӣ кардани хатҳои охирин:</strong> Дар поёни ҳар хати ҷанба, кушоки холӣ бояд кор кунад, то зарраҳои хурдтар ва регҳои нозук бо фишори баланде, ки дар поёни хат мавҷуд аст, аз система берун шаванд. Ин марҳила барои анорӣ, ки ҳаяҷони баланд ба камшавии миқдори об дорад, ҳатмист.</li>\n  <li><strong>Шустани кимиёвӣ:</strong> Дар ҳолати ошкор шудани кам шудани миқдори оби баромади тамғагузорҳо, аз кислотаи ситрик ё кислотаи гидроклерик бо ҳадди кам (1 то 2 фоиз) истифода баред. Кислота зарраҳои калсий ва магнийро ҳал мекунад. Пас аз шустани қалтӣ, ҳатман бо оби сард то ҳамои pH пурра шӯед.</li>\n</ol>\n<p>Нуқтаи муҳим: ҳаргиз кислота ва хлорро дар як системае, ки металҳои вазнин дорад, ҳамзамон истифода накунед, магар ин ки даромади мувофиқ (24 соат) доред, то аз хароши лӯла ва пайвастгоҳҳо пешгирӣ карда шавад. Барои шиносоии бештар бо асосҳои амният ва таҷҳизоти лозимӣ дар обори тамғагузорӣ, матлаби обори тамғагузориро санҷед.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/نگهداری-شنبلیله-با-نوار-تیپ-نکات-کلیدی-تصویر-شاخص.webp" alt="نگهداری شنبلیله با نوار تیپ: نکات کلیدی - تصویر 1"/><figcaption>Дармонка ва нигоҳубини лентаи ҳанговии ғазоки шанблиле</figcaption></figure>\n\n<h2>Идоракунии лағвоти зистонӣ ва нисбатан дар лентаи ҳанговӣ</h2>\n<p>Лағвоти зистонӣ ба монанди зарулаҳо, бактерияҳо ва зарулаҳои сабз метавонанд дарҳои баромадиро тез пӯшонанд. Шанблиле набототиест, ки дар шароити намнокунии пайдарпай барои рушди занбоорҳо дар замин ҳалкунанда аст, аммо ин намӣ дар лентаи ҳанговӣ маҳаллӣ аст ва агар система солим бошад, аз рушди микробиҳои нохӯҳ шуда дар лӯлӯҳо пешгирӣ мекунад. Аммо, истифодаи гازی хлор ё хлорин ҳамчун пасткунонишакунанда, усули стандартӣ барои кишоварони саноатӣ аст.</p>\n<ul>\n  <li><strong>Хлорин:</strong> Дар шароитҳое, ки обҳои зери замин дорои бактерияҳои сулфури (Sulfur Bacteria) мебошанд, истифодаи хлорини 200 миллиграмм дар килограмм дар аввали система ин микробиҳоро нест мекунад.</li>\n  <li><strong>Фильтрсияи дақиқ:</strong> Пеш аз ворид шудани об ба лентаи ҳанговӣ, истифодаи фильтри турбина (Turbine Filter) бо суспенсияи 100 микрон ё шабакаи филтри мувофиқ барои шанблиле зарур аст. Ин филтр аз ворид шудани чӯбин (Silt) ба ҳангавҳо пешгирӣ мекунад.</li>\n</ul>\n\n\n\n<h2>Нуқтаҳои амалӣ дар давраи ғазор ва кампани шанблиле</h2>\n<p>Дар тӯли сикли ҷунбиши ҷамба, рафтори наҳафҳо ба шароити иқлимӣ вобаста аст. Дар фаслҳои гарм, васеъшавии гармии полиетилений лӯлаҳоро сахт мекунад. Дар ин шароит, агар наҳафҳо ба хуки хунук ё бо анҷомеи металлӣ тӯсишанд, эҳтимоли поришан дорад.</p>\n<h3>Барномасозии обёрӣ мутобиқи тақозоти ҷамба</h3>\n<p>Ҷамба ба обёрии кам ва мунтазам ниёз дорад. Агар наҳафҳо бо саросирии камтар аз 1/4 ё 1/2 литр дар соат истифода шаванд, чуқурии нуфури оби беҳтар мешавад. Аз обориҳои вақтан ва узун, ки фишори зиёд ба сохтори хок атрофи наҳаф меоваранд, худдорӣ кунед. Ин вазъият ба пайдоишани сӯрохиҳои ҳавоӣ, ҷудошавии наҳаф аз нафаси хок ва камшавии самаранокӣ оварда мерасонад.</p>\n<p>Барои беҳтар кардани миқдори оби зарурӣ, шумо метавонед ба дастурҳои ихтисосии маҳсулоти дигаре, ки аз ҷиҳати тақозоти об монанди онҳо ҳастанд, муроҷиат кунед. Масалан, омӯзиш дар бораи <a href="https://navar-abyari.ir/%D9%85%D9%82%D8%AF%D8%A7%D8%B1-%D8%A8%D8%B0%D8%B1-%D8%A7%D8%B3%D9%BE%D8%B1%D8%B3-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/" target="_blank">миқдори боби аспресс дар гектар</a> метавонад диди шуморо дар бораи идоракунии зичии боркунии ва таъсири он ба системаи обёрӣ ва тақозоти саросирии наҳаф васеъ кунад.</p>\n\n<h2>Кашфи мушкилоти маъмули наҳаф</h2>\n<p>Қобилияти шинохти зуд ба хобкорӣ калиди нигоҳдории муваффақ аст. Дар ҳолати дида шудани хукидӣ дар охири хатҳо ё номуносибати ҷунбиши хокиҳо, рӯйхатҳои зеринро санҷед:</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/نگهداری-شنبلیله-با-نوار-تیپ-نکات-کلیدی-کاربرد-عملی.webp" alt="نگهداری شنبلیله با نوار تیپ: نکات کلیدی - تصویر 2"/><figcaption>нигоҳубinii ва парҳезони лентаи чанқори парҳези кадуни</figcaption></figure>\n<ul>\n  <li><strong>Кам шудани оварии об:</strong> Одатан боиси он ҷамъшавии калсий ё воридшавии лодост. Шустаниш бо кислота тавсия мешавад.</li>\n  <li><strong>Шикастани лентаи чанқорӣ:</strong> Одатан ба сабаби гузаштани таҷҳизоти механикӣ болои лента рух медиҳад. Лентаро шикастаро бо капсулаи таъмиркунӣ ё пӯлолани қатъӣ иваз кунед.</li>\n  <li><strong>Резидан аз пайвастҳо:</strong> Санҷед, ки оё лентаи чанқорӣ дуруст дар гузаришгоҳ (кӯплинг) ҷойгирифтааст. Кӯчидани лента дар гузаришгоҳ сабаби маъмули резидан аст.</li>\n  <li><strong>Пӯшиши пурраи хат:</strong> Дар ин ҳолат, филтри воридаро санҷед. Зароки филтри асосӣ тамоми системаро бемаъно мекунад.</li>\n</ul>\n\n<h2>Нуқтаҳои нигоҳубини фасли истироҳат ва анбордорӣ</h2>\n<p>Баъди ғавоси маҳсулоти занҷобил, наварҳои дриперро ё бояд ҷамъ овард ва анбор кард ё қарор диҳанд. Барои ҷамъ овардани дуруст:</p>\n<ol>\n  <li>Наварро оҳиста аз хок кашед, то ки пароканда нашудааст.</li>\n  <li>Наварро бо якпорача ба чархи спайрел ё сими пичок пичконед, вале на чунон часе бошад, ки шакли асли навор тағйир йабад.</li>\n  <li>Пайвастҳоро бо пухтумуҳҳои ислоҳ пӯшонед, то дар натиҷаи ҳаракат осеб надиҳанд.</li>\n  <li>Чархҳоро дар гараж ё анбори хушк ва хунук ҷойгир кунед. офтоби рост, сабаби асосии пайдои пиршавӣ ва сахт шудани наварҳои дрипер мебошад.</li>\n</ol>\n<p>Барои фаҳмиши беҳтари ҷойгиркунии лӯлаҳо ва системаҳои алоқаманд, мавзӯъро хонед <a href="https://navar-abyari.ir/how-to-determine-tape-irrigation-points/" target="_blank">Таври муайян кардани нуқтаҳои обдорӣ бо лентаи дарилӣ</a> Ин метавонад роҳнамаи амалии шуморо барои ҷойгирсозии дурусти система дар бӯстонҳо бошад.</p>\n\n\n\n<h2>Саволҳои зуд-зуд пурсидашуда (FAQ)</h2>\n<p><strong>1. Оё бояд аз лентаи дарилӣ барои чанд фавсали пайдарпай истифода бурд?</strong><br>Бале, бо риоя кардани принсипҳои парвариш, захирагузории дуруст ва шустушуи солӣ, лентаи дарилӣ метавонад то 2 то 3 фавсали кунун бартараф шавад. Пас аз ин, кам шудани оқими дарилҳо зиёд мешавад ва иваз кардан тавсия дода мешавад.</p>\n<p><strong>2. Беҳтарин вақти шустушуи лентаи дарилӣ чӣ вақт аст?</strong><br>Беҳтарин вақт лаҳзаи анҷоми ҳар як обдории асосӣ ва охири фавсали кунун аст. Шустушуи фаслӣ ҷамъовардҳои яксолаи қаҳрамонро хомӯш мекунад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/نگهداری-شنبلیله-با-نوار-تیپ-نکات-کلیدی-جزئیات-فنی.webp" alt="نگهداری شنبلیله با نوار تیپ: نکات کلیدی - تصویر 3"/><figcaption>парвариши лентаи дарилӣ барои бӯстон ҷондунокӣ</figcaption></figure>\n<p><strong>3. Чӣ тавр метавонам муайян кунам, ки ленти нақбдор ифлос шудааст?</strong><br>Бо ташаҳҳуси шароити баромадани оби хориҷшаванда. Агар шиддати баромадани намунавҳаҳои об дар поёни лента бо нуқтаҳои оғозии фарқ кунанда дошта бошад ё агар об ба сурати паҳлӯкӣ ворид шавад, нуқобҳо пурраванд.</p>\n<p><strong>4. Оё истифодаи филтри диафрагмагӣ барои чучунок кофист?</strong><br>Филтри диафрагмагӣ барои зарраҳои осубадашуда мувофиқ аст, вале барои зарраҳои хурди хокӣ (Silt), истифодаи филти тӯринӣ ё тобиш (Screen) бо таҳшинии баланд (150 микрон аз коҳ) тавсия дода мешавад.</p>\n<p><strong>5. Чӣ тавр фишори обро дар дохили ленти нақбдор танзим кунам?</strong><br>Барои чучунок, фишори корӣ 1/5 то 2 бар кофист. Фишори баландтар фишорро зиёд мекунад, вале хавфи паҳлӯки оби рӯи хокро зиёд мекунад.</p>\n\n<h2>Хулоса</h2>\n<p>Нигоҳдории ленти нақбдор дар парвариши чучунок равандест, ки бо барномарезии мунтазам ва шиноси дақиқи мушкилҳои ин система, аз сарф-у-харҷи арзиши баланд пешгирӣ мекунад. Бо такя бар принсипҳои тозакунии кимиёвӣ ва механикӣ, истифодаи филтрасияи мувофиқ ва анбордории дуруст, метавон аз кори бомулоҳизаи ленти нақбдор дар тамоми мавсимҳои парвариш таъмин шуд. Диққат ба ин масъалаҳо на танҳо бартарафии ҳосили чучунокро нигоҳ медорад, балки дар замони дарозмӯҳлат, хароҷоти умумии деҳоро паст меорад. Мо дар <a href="https://navar-abyari.ir/mikyori-hosili-marza-dar-yek-gektar-rahnamoi-purra/" target="_blank">Нигоҳубиноии маҳсулот дар гектар</a> Мо ҳамеша таъкид мекардем, ки системаҳои обкорӣ дилдоди деҳқониҳои муосир мебошанд ва парвариши онҳо қадаме ба сӯи кишоварзӣи пайдогар аст.</p>','Пуррагидҳогирии нишонаи Тип дар кишт кардани шубилла: Принсипҳои илмӣ ва амалӣ','Шаблиҷе як растии ҳассос ба тиллат мебошад, ки истифодаи системаи наварии қатқулӣ самаранокии обёрро ба инкишоф мерасонад. Аммо ин система ба парвариши махсус ниёз дорад. Дар ин дастур мо меомӯзем, ки чӣ тавр бо риояи асосҳои нигоҳдорӣ, аз хастагии дағҷонивӣ ва кам шудани фишор пешгирӣ кунем.','publish','closed','closed','guide-ripe-strip-shubila-farming',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
