INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддима дар бораи аҳамияти обориши дақиқ дар парвариши бек (кастани)</h2><p>Бек (кастани), баҳисоби яке аз маҳсулоти муҳими боғу боғзор ва саноатӣ, ба сабаби ниёзи баланд ба об ва ғизо, ба идоракунии дурусти манбаъҳо вобаста аст. Дар солҳои охир, бо эҳтиром ба маҳдудии манбаъҳои обии ва ниёз ба зиёд кардани самаранокии замин, истифодаи системаҳои обориши фишордор, хусусан <strong>шарти тиб</strong>ба як имкони ғайриимконбарои деҳқонон табдил ёфтааст. Мигари бек (кастани) дар як гектар бо шарти тиб нисбат ба усулҳои анъанавӣ (баронӣ ё часмагӣ) то 30 то 50 фоиз зиёд мешавад. Ин система бо тақсимоти якхелаи об ва моддаҳои ғизоӣ дар минтақаи решаӣ, стресси обнокӣ ва нокофӣи унсурҳоро кам карда, барои афзоиши беҳтари коб, барг ва мевоварӣ сабб мешавад. Дар ин қисми мақола, мақсади мо пешниҳоди назари умумӣ дар бораи имкониятҳои истеҳсолии бек (кастани) бо истифода аз ин технология мебошад.</p><p>Бояд диққат дод, ки даст ёфтани самаранокии баланд бе риояи асосҳои агронумии (кишовӣ) мумкин нест. Шарти тиб танҳо асбоб аст; калиди муваффақият дар интихоби нусҳо мувофиқ, сабти ниҳол, давомнокии ғизо ва идоракунии зараранокон ва бемориҳо нуқш дорад. Бо идомаи хондан, мо дар бораи ҷузъҳои сершуморе, ки ба <strong>мигари бек (кастани) дар як гектар</strong> сироят мекунад, супурем.</p><h2>Кӯдаҳое, ки мигари бек (кастани) дар як гекарро муайян мекунанд</h2><p>Барои дарки ёнаккал ҳаҷми истеҳсоли каббаҳ, бояд тағйирёбандаҳои асосиро шиносд. Ин омилҳо ба ду гурӯҳи беруна (муҳитӣ) ва дохилӣ (идоракунии ҷонибон) тақсим мешаванд.</p><h3>1. Марқаби каббаҳ ва намуди генетикии ҳосилнокӣ</h3><p>Интихоби марқаби муносиб қадами аввал барои таъмини ҳосилнокии баланд аст. Марқаби ғафсагирон одатан ҳосилнокии пасттар доранд, вале имконияти ду бор карданро дар як сол фароҳам меоранд. Марқаби ғафсагир то дерсоғгир вобаста ба минтақаҳои ҷуғрофӣ амал мекунад. Баъзе марқаби қоросонӣ ва гулӣ маъруфанд, ки бо системаи наваруни типӣ муносибати беҳтар зоҳир мекунанд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/میزان-برداشت-کدو-در-هکتار-با-نوار-تیپ-تصویر-شاخص.webp" alt="میزان برداشت کدو در هکتار با نوار تیپ - تصویر 1"/><figcaption>crop yield per hectare drip irrigation каббаҳ</figcaption></figure><h3>2. Масофаи ғармкунӣ ва зичии ҷамъҷоии растаниҳо</h3><p>Масофаҳои ғармкунӣ байни сатҳҳо ва дар дохили сатҳҳо аз муҳимтарин омилҳои идоракунии ҷонибон мебошанд. Ғармкунии зич метавонад ба рақобат барои рӯшноӣ ва об оварда расонида ва дар натиҷа анҷоми меваҳо (ҳамешакии шумораи меваҳо метавонад якхела ё каме зиёдтар бошад) ба меҳнокии кам расонад. Дар системаҳои наваруни типӣ, ба сабаби таъсири беҳтари решаҳо, метавон аз масофаҳои каме дуртар истифода бур, то рақобати решаҳоро пешгирӣ кунад. Масалан, масофаи 450 сантиметр байни сатҳҳо ва 50 то 60 сантиметр байни гиёҳҳо яке аз меъёрҳои маъмулӣ дар минтақаҳои гарми Ҷумҳурии Ирони Ҷанубӣ мебошад.</p><h3>3. Идоракунии намҳои хок</h3><p>Каббаҳ ғунунист, ки намҳои баробарро афзал дорад. Тағйирёбии намои намҳо метавонад ба меҳнокии меваҳо ё таъми бидуни лаззати он оварда расонад. Наваруни типӣ бо поливи мутаносиб ва камҳаҷмӣ ба нигоҳдории намҳои устувор дар решаҳо кӯмак мекунад. Пайгирии намҳои хок бо материалҳои сода ё сенсорҳои рақамӣ барои беҳтарсозии вақт ва ҳаҷми полив ҳайатӣ аст.</p><h2>Коркардонии навъҳо ва системаҳои намукадудӣ (drip)</h2><p>Барои фаҳмиши беҳтар, мо муқоисаи коркардиро байни навъҳои гуногун дар шароити намукадудӣ дида мебароем. Маълумоти дар самтҳо нишон медиҳад, ки навъҳои тиҷоратӣ бо муқовимати нисбати баланд ба фурӯшӣ ҳосилнокии беҳтар доранд. Агар хоҳед бо маълумоти монанд барои дигар маҳсулоти решагӣ ва мевагӣ шинос шавед, метавонед мақолаи "Шароити баландшудаи ҳосилнокӣ ба таври бонусӣ"-ро омӯзед, ки мафҳумҳои монанд дорад. Инчунин барои фаҳмиши чуқуртари динамичеси бозори маҳсулоти боғӣ, мушоҳида <a href="https://navar-abyari.ir/irrigation-tape-squash-guide/">Роҳнамои намукадудӣ барои каду (Англисӣ)</a> метавонад фоидаовар бошад.</p><p>Намукадудӣ хатҳои гуногун дорад (одатан аз 8 то 16 миллиметр). Интихоби хати намукадудӣ ба суръати ҷараён ва дар натиҷа миқдори оби додашуда дар ҳар як даври обёрӣ таъсир мерасонад. Дар шароити хокҳои сабук, ки обниши (drainage) баланд доранд, тавсия дода мешавад, ки намукадудҳои хатбаландтар ё шумораи бештари намукадудҳо дар ҳар қатёр истифода шаванд, то имконияти решагӣ пур карда шавад. Баъд аз он, дар хокҳои вазнинтар, намукадудҳои нилтон бо шумораи бештар метавонад аз вайроншавии решаҳо пешгирӣ кунад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/میزان-برداشت-کدو-در-هکتار-با-نوار-تیپ-کاربرد-عملی.webp" alt="میزان برداشت کدو در هکتار با نوار تیپ - تصویر 2"/><figcaption>ҳосилии ҳектарии намукадудӣ каду</figcaption></figure><div class="img-container" ></div><h2>Диадҳои амалӣ барои зиёд кардани ҳосилнокӣ бо намукадудӣ</h2><ul><li><strong>Тайёркунии вақти кардани:}</strong> Кортири (охири тӯлиф или оғоз баҳор) дар минтақаҳои гарм имконияти истифода аз фасли дуюми кортиро фароҳам меорад. Кортири дер бахсро зиёд мекунад, ки ба сабаби гармии шадиди тобистон ифлорӣ паст шудааст.</li><li><strong>Муҳофизат бо чумӯр ва пластик:</strong> Истифодаи плёнкаи шашеҳо (муҳофизат) аз пластики шаффоф ё ним-шаффоф дар паҳлӯи системаи қатрамонӣ, намии хокро нигоҳ медорад ва рӯйиши аввалина гиёҳро тез мекунад. Ин усул махсусан дар моҳҳои сард бисёр қобилият дорад.</li><li><strong>Гузоштани тағозот (fertigation):</strong> Системаи қатрамонӣ заминаи беҳтарин барои иҷрои тағозот аст. Афзудани моддаҳои тағозоткунандаи химиявии ҳалшуда ба об барои обёрӣ, самаранокии ивораҳоро ба ноқис мерасонад. Моддаҳои тағозоткунанда, ки аз азот доранд, дар марҳилаҳои аввали рӯйиш ва калий доранд, дар марҳилаҳои ташаккули мева зарурӣ мебошанд.</li><li><strong>Идоракунии намӣ бо пашидани чумӯр:</strong> Агар имкон бошад, истифодаи пашидани чумӯр (Mulching) дар паҳлӯи система, пешгирии оҳанин мекунад.</li></ul><h3>Идоракунии зараранокҳо ва бемориҳои реша</h3><p>Сувири доимӣ ва якхела метавонад муҳити муносиби барои патогенҳои ришаварӣ аз қабили Fusarium ва Phytophthora эҷод кунад. Барои пешгирӣ, гардиши соланоамаз дарора ва каббак ва истифодаи багъҳои фаъолкунандаи микробӣ тавсия дода мешавад. Инчунин таъхир дар кӯшиш метавонад ба кам шудани шумораи аввалини зараррасонҳо кӯмак расонад.</p><h2>Таҳлили иқтисодӣ ва муқоиса бо дигар маҳсулот</h2><p>Барои деҳқонон, муқоисаи баромади иқтисодии каббак бо маҳсулоти рақибон дар ҳангоми қабули ҳалли кӯшиш нақши калидӣ дорад. Мисолан, <a href="https://navar-abyari.ir/%D9%85%DB%8C%D8%B2%D8%A7%D9%86-%D8%A8%D8%B1%D8%AF%D8%A7%D8%B4%D8%AA-%D8%A7%D8%B1%D8%B2%D9%86-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/">Миқдори ҳосилорӣ дар гектар</a> Ва миқдори ҳосилории наҷошӣ дар гектар низ бо истифода аз системаҳои монанди нафту тире ва қатқатӣ беҳтар кардан мумкин аст. Каббак аз сабаби давраи ниҳоят қисми нисбати кӯтоҳ ва тобоварии баланди мева ба нақлиёт дар бозор ҷойи махсус дорад.</p><table><thead><tr><th>Параметр</th><th>Усули таъсир ба ҳосилорӣ</th><th>Миқдори тавсияшуда (доруворӣ)</th></tr></thead><tbody><tr><td>Фосилаи нишаст</td><td>Давомии рӯшноӣ ва решаҳо</td><td>450 × 60 сантиметр</td></tr><tr><td>Мiqдори обёрӣ</td><td>Стресси решаҳо</td><td>50 то 70 литр барои ҳар бутта дар моҳ</td></tr><tr><td>Мувозунати киёриш</td><td>Нӯмунӣ</td><td>1:1:2 (дар марҳабаи истеҳсолот)</td></tr></tbody></table><div class="img-container" ></div><h2>Саволҳои оммавӣ (FAQ)</h2><h3>Оё наворҳои Tipi барои ҳамаи иқлимҳо мувофиқанд?</h3><p>Бале, аммо танзимоти он гуногун аст. Дар минтақаҳои хушк, давраи ороёнӣ бояд кӯтоҳтар бошад. Дар минтақаҳои намнок, хатари бемориҳои решаҳо баландтар аст ва назорати дақиқи намӣ зарур аст. Дар минтақаҳое, ки ба мушкилоти монан дар меҳоварии маҳсулоти дигар рӯбарӯанд, ба... <a href="https://navar-abyari.ir/%d9%85%db%8c%d8%b2%d8%a7%d9%86-%d8%a8%d8%b1%d8%af%d8%a7%d8%b4%d8%aa-%d8%b3%d9%88%db%8c%d8%a7-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">Ҳаҷми меҳоварии соя дар гектар</a> Метавонад дидҳои хубро дар бораи идоракунии манбаъҳо диҳад.</p><h3>Чӣ тавр ҳаҷми меҳоварии хурма (баҳоринг) дар гектарро ҳисоб мекунем?</h3><p>Формулаи сода барои тахмин: шумораи буғумони киштшуда × вазни миёнаи мева × шумораи меваҳои омода барои меҳоварӣ дар ҳар буғумон. Ҳадафи идеалӣ расидан ба 30 то 50 тонна дар гектар дар шароити хуб аст. Ин рақамҳо вобаста ба номгузорӣ ва идоракунии дигар метавонад тағйир ёбад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/میزان-برداشت-کدو-در-هکتار-با-نوار-تیپ-جزئیات-فنی.webp" alt="میزان برداشت کدو در هکتار با نوار تیپ - تصویر 3"/><figcaption>бардош заҳуб дар гектар, обкоробкутании қатқат, хурма</figcaption></figure><h3>Оё системаи қатқатӣ бо назардошти шитоб беҳтар аст ё на?</h3><p>Шитоб хароҷоти камтар ва насби осонтарро дорад ва барои маҳсулоти серҷиддӣ ба мисоли хурма хеле муносиб аст. Қатқатӣ барои намудҳои мушаххастар ва идоракунии дақиқтар коркардӣ мекунад, вале хароҷоти баландтар ва зарурати идома дорад.</p><div class="img-container" ></div><h2>Хулоса ва чашм-андози оянда</h2><p>расидан ба омаддӯшии афзун <strong>ҳаҷми бардошти хурма дар гектар</strong> ба назари қоидаи омехта интихоби навъи мувофиқ, фазои гузоштани дуруст ва истифодаи системаҳои обкоробкунии каммасарф ба мисоли шитоб ниёз дорад. Сармогузорӣ дар ин технологияҳо баргашти сармои пазиршавандагиро бо зиёд шудани самаранокӣ ва кам шудани хароҷоти об ва коркарди дастӣ таъмин мекунад. Ба деҳқонон тавсия мегардад, ки аз назорати даимии хок ва растани нигарониш накунанд ва дар ҳолати ниёз ба маслиҳати бештар, аз манбаъҳои ихтисосӣ ба мисоли <a href="https://navar-abyari.ir/irrigation-tape-squash-guide/">раҳнамои шитоб барои хурма</a> Истифода кунанд. Ояндаи парвариши турби бо якҷоякунии технологияҳои зеҳнӣ (масалан, ҳосилкунаки намнокӣ ва назорати бетартиб) равшантар хоҳад буд.</p>\n<p><strong>Маводи алоқаманд:</strong> <a href="https://navar-abyari.ir/%D9%85%DB%8C%D8%B2%D8%A7%D9%86-%D8%A8%D8%B1%D8%AF%D8%A7%D8%B4%D8%AA-%DA%AF%D8%B4%D9%86%DB%8C%D8%B2-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/">D985DB8CD8B2D8A7D986 D8A8D8B1D8AFD8A7D8B4D8AA DAAFD8B4D986DB8CD8B2 D8AFD8B1 D987DAA9D8AAD8A7D8B1</a></p>','Мизоби нӯрӯз бо нури типи: Рӯҳсоники боварӣ барои зиёд кардани натиҷаҳои кор','Корӯни муосир бо истифода аз технологияҳои нав оварии об, ба монанди системаи оварии бо барибҳо, метавонанд ҳаҷми ҳосили каду дар ҳектарро ба таври назаррас зиёд кунанд. Ин ғайр аз он, ки дар кам кардани сарфи об самаранок аст, бо парвариши дақиқи ниҳоӣ ба сифат ва ҳаҷми ҳосили маҳсулот ҳам таъсири дорад. Дар поён ба баррасии тафсилоти техникӣ, шартҳои иътирофи кишт ва нуқтаҳои асосӣ барои расидан ба ҳосилмалии максималии каду бо системаи оварии бо барибҳо мерасем.','publish','closed','closed','mizobi-nooruz-bo-nuri-tipi',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
